(11442,44,212,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Haloalkanes_and_Haloarenes-image43.png'),
(11443,44,213,'paragraph',NULL,'For a given alkyl group, the reactivity of the halide, R-X, follows the same order in both the mechanisms R–I> R–Br>R–Cl>>R–F.','[{"s": "For a given alkyl group, the reactivity of the halide, R-X, follows the same order in both the mechanisms R–I> R–Br>R–Cl>>R–F.", "t": "text"}]',NULL,NULL,NULL),
