(11453,44,223,'paragraph',NULL,'(ii) C 6 H 5 CH 2 Br , C 6 H 5 CH(C 6 H 5 ) Br , C 6 H 5 CH(CH 3 ) Br , C 6 H 5 C(CH 3 )(C 6 H 5 ) Br','[{"s": "(ii) C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": "CH", "t": "text"}, {"s": "2", "t": "text"}, {"s": "Br", "t": "text"}, {"s": ", C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": "CH(C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": ")", "t": "text"}, {"s": "Br", "t": "text"}, {"s": ", C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": "CH(CH", "t": "text"}, {"s": "3", "t": "text"}, {"s": ")", "t": "text"}, {"s": "Br", "t": "text"}, {"s": ", C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": "C(CH", "t": "text"}, {"s": "3", "t": "text"}, {"s": ")(C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": ")", "t": "text"}, {"s": "Br", "t": "text"}]',NULL,NULL,NULL),
