(13289,45,289,'paragraph',NULL,'In the case of solids, it is observed that the trans isomer has higher melting point than the cis form.','[{"s": "In the case of solids, it is observed that the trans isomer has higher melting point than the cis form.", "t": "text"}]',NULL,NULL,NULL),
(13290,45,290,'paragraph',NULL,'Geometrical or cis-trans isomerism is also shown by alkenes of the types XYC = CXZ and XYC = CZW','[{"s": "Geometrical or cis-trans isomerism is also shown by alkenes of the types XYC = CXZ and XYC = CZW", "t": "text"}]',NULL,NULL,NULL),
