INSERT INTO `ncert_book_blocks` (`id`, `chapter_id`, `idx`, `type`, `level`, `text`, `content`, `status`, `pyq_ids`, `image_url`) VALUES
(13568,45,568,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Hydrocarbons-image190.png'),
(13569,45,569,'paragraph',NULL,'Protonated Nitronium nitric acid ion','[{"s": "Protonated Nitronium nitric acid ion", "t": "text"}]',NULL,NULL,NULL),
(13570,45,570,'paragraph',NULL,'It is interesting to note that in the process of generation of nitronium ion, sulphuric acid serves as an acid and nitric acid as a base. Thus, it is a simple acid-base equilibrium.','[{"s": "It is interesting to note that in the process of generation of nitronium ion, sulphuric acid serves as an acid and nitric acid as a base. Thus, it is a simple acid-base equilibrium.", "t": "text"}]',NULL,NULL,NULL),
(13571,45,571,'paragraph',NULL,'(b) Formation of Carbocation (arenium ion): Attack of electrophile results in the formation of σ-complex or arenium ion in which one of the carbon is sp3 hybridised.','[{"s": "(b) Formation of Carbocation (arenium ion):", "t": "text"}, {"s": "Attack of electrophile results in the formation of σ-complex or arenium ion in which one of the carbon is sp3 hybridised.", "t": "text"}]',NULL,NULL,NULL),
(13572,45,572,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Hydrocarbons-image117.png'),
(13573,45,573,'paragraph',NULL,'sigma complex (arenium ion)','[{"s": "sigma complex (arenium ion)", "t": "text"}]',NULL,NULL,NULL),
(13574,45,574,'paragraph',NULL,'The arenium ion gets stabilised by resonance:','[{"s": "The arenium ion gets stabilised by resonance:", "t": "text"}]',NULL,NULL,NULL),
(13575,45,575,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Hydrocarbons-image125.png'),
(13576,45,576,'paragraph',NULL,'Sigma complex or arenium ion loses its aromatic character because delocalisation of electrons stops at sp3 hybridised carbon.','[{"s": "Sigma complex or arenium ion loses its aromatic character because delocalisation of electrons stops at sp3 hybridised carbon.", "t": "text"}]',NULL,NULL,NULL),
(13577,45,577,'paragraph',NULL,'(c) Removal of proton: To restore the aromatic character, σ -complex releases proton from sp3 hybridised carbon on attack by [AlCl4]– (in case of halogenation, alkylation and acylation) and [HSO4]– (in case of nitration).','[{"s": "(c) Removal of proton:", "t": "text"}, {"s": "To restore the aromatic character, σ -complex releases proton from sp3 hybridised carbon on attack by [AlCl4]– (in case of halogenation, alkylation and acylation) and [HSO4]– (in case of nitration).", "t": "text"}]',NULL,NULL,NULL),
(13578,45,578,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Hydrocarbons-image181.png'),
(13579,45,579,'heading',4,'Addition reactions',NULL,NULL,NULL,NULL),
(13580,45,580,'paragraph',NULL,'Under vigorous conditions, i.e., at high temperature and/ or pressure in the presence of nickel catalyst, hydrogenation of benzene gives cyclohexane.','[{"s": "Under vigorous conditions, i.e., at high temperature and/ or pressure in the presence of nickel catalyst, hydrogenation of benzene gives cyclohexane.", "t": "text"}]',NULL,NULL,NULL),
