(14773,46,122,'heading',3,'12.4 CLASSIFICATION OF ORGANIC COMPOUNDS',NULL,NULL,NULL,NULL),
(14774,46,123,'paragraph',NULL,'The existing large number of organic compounds and their ever-increasing numbers has made it necessary to classify them on the basis of their structures. Organic compounds are broadly classified as follows:','[{"s": "The existing large number of organic compounds and their ever-increasing numbers has made it necessary to classify them on the basis of their structures. Organic compounds are broadly classified as follows:", "t": "text"}]',NULL,NULL,NULL),
(14775,46,124,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Organic_Chemistry_Some_Basic_Principles_and_Techniques-image172.png'),
(14776,46,125,'heading',4,'I. Acyclic or open chain compounds',NULL,NULL,NULL,NULL),
(14777,46,126,'paragraph',NULL,'These compounds are also called as aliphatic compounds and consist of straight or branched chain compounds, for example:','[{"s": "These compounds are also called as aliphatic compounds and consist of straight or branched chain compounds, for example:", "t": "text"}]',NULL,NULL,NULL),
