(14928,46,277,'paragraph',NULL,'2-Chloro-4-methylanisole 4-Ethyl-2-methylaniline','[{"s": "2-Chloro-4-methylanisole 4-Ethyl-2-methylaniline", "t": "text"}]',NULL,NULL,NULL),
(14929,46,278,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Organic_Chemistry_Some_Basic_Principles_and_Techniques-image59.png'),
(14930,46,279,'paragraph',NULL,'3,4-Dimethylphenol','[{"s": "3,4-Dimethylphenol", "t": "text"}]',NULL,NULL,NULL),
(14931,46,280,'paragraph',NULL,'When a benzene ring is attached to an alkane with a functional group, it is considered as substituent, instead of a parent. The name for benzene as substituent is phenyl (C 6 H 5 -, also abbreviated as Ph).','[{"s": "When a benzene ring is attached to an alkane with a functional group, it is considered as substituent, instead of a parent. The name for benzene as substituent is phenyl (C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": "-, also abbreviated as Ph).", "t": "text"}]',NULL,NULL,NULL),
(14932,46,281,'paragraph',NULL,'Problem 12.10','[{"s": "Problem 12.10", "t": "text"}]',NULL,NULL,NULL),
(14933,46,282,'paragraph',NULL,'Write the structural formula of:','[{"s": "Write the structural formula of:", "t": "text"}]',NULL,NULL,NULL),
(14934,46,283,'paragraph',NULL,'(a) o-Ethylanisole, (b) p-Nitroaniline,','[{"s": "(a) o-Ethylanisole, (b) p-Nitroaniline,", "t": "text"}]',NULL,NULL,NULL),
(14935,46,284,'paragraph',NULL,'(c) 2,3 - Dibromo -1 - phenylpentane,','[{"s": "(c) 2,3 - Dibromo -1 - phenylpentane,", "t": "text"}]',NULL,NULL,NULL),
(14936,46,285,'paragraph',NULL,'(d) 4-Ethyl-1-fluoro-2-nitrobenzene.','[{"s": "(d) 4-Ethyl-1-fluoro-2-nitrobenzene.", "t": "text"}]',NULL,NULL,NULL),
