(15752,47,51,'paragraph',NULL,'Write chemical equations for the following reactions:','[{"s": "Write chemical equations for the following reactions:", "t": "text"}]',NULL,NULL,NULL),
(15753,47,52,'paragraph',NULL,'(i) Reaction of ethanolic NH 3 with C 2 H 5 Cl.','[{"s": "(i) Reaction of ethanolic NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "with C", "t": "text"}, {"s": "2", "t": "text"}, {"s": "H", "t": "text"}, {"s": "5", "t": "text"}, {"s": "Cl.", "t": "text"}]',NULL,NULL,NULL),
(15754,47,53,'paragraph',NULL,'(ii) Ammonolysis of benzyl chloride and reaction of amine so formed with two moles of CH 3 Cl.','[{"s": "(ii) Ammonolysis of benzyl chloride and reaction of amine so formed with two moles of CH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "Cl.", "t": "text"}]',NULL,NULL,NULL),
