(15777,47,76,'paragraph',NULL,'Write structures and IUPAC names of','[{"s": "Write structures and IUPAC names of", "t": "text"}]',NULL,NULL,NULL),
(15778,47,77,'paragraph',NULL,'(i) the amide which gives propanamine by Hoffmann bromamide reaction.','[{"s": "(i) the amide which gives propanamine by Hoffmann bromamide reaction.", "t": "text"}]',NULL,NULL,NULL),
(15779,47,78,'paragraph',NULL,'(ii) the amine produced by the Hoffmann degradation of benzamide .','[{"s": "(ii) the amine produced by the Hoffmann degradation of benzamide", "t": "hl"}, {"s": ".", "t": "text"}]','marked','["270801"]',NULL),
(15780,47,79,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(15781,47,80,'paragraph',NULL,'(i) Propanamine contains three carbons. Hence, the amide molecule must contain four carbon atoms. Structure and IUPAC name of the starting amide with four carbon atoms are given below:','[{"s": "(i) Propanamine contains three carbons. Hence, the amide molecule must contain four carbon atoms. Structure and IUPAC name of the starting amide with four carbon atoms are given below:", "t": "text"}]',NULL,NULL,NULL),
(15782,47,81,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/Organic_Compounds_Containing_Nitrogen-image80.png'),
(15783,47,82,'paragraph',NULL,'Butanamide','[{"s": "Butanamide", "t": "text"}]',NULL,NULL,NULL),
(15784,47,83,'paragraph',NULL,'(ii) Benzamide is an aromatic amide containing seven carbon atoms. Hence, the amine formed from benzamide is aromatic primary amine containing six carbon atoms.','[{"s": "(ii) Benzamide is an aromatic amide containing seven carbon atoms. Hence, the amine formed from benzamide is aromatic primary amine containing six carbon atoms.", "t": "text"}]',NULL,NULL,NULL),
(15785,47,84,'paragraph',NULL,'Organic_Compounds_Containing_Nitrogen-image8.png Aniline or benzenamine','[{"s": "Organic_Compounds_Containing_Nitrogen-image8.png", "t": "img", "alt": ""}, {"s": "Aniline or benzenamine", "t": "text"}]',NULL,NULL,NULL),
