(16299,48,58,'paragraph',NULL,'Sodium','[{"s": "Sodium", "t": "text"}]',NULL,NULL,NULL),
(16300,48,59,'paragraph',NULL,'tetrahydroxoaluminate(III)','[{"s": "tetrahydroxoaluminate(III)", "t": "hl"}]','marked','["113919"]',NULL),
(16301,48,60,'heading',4,'(iii) Reactivity towards halogens',NULL,NULL,NULL,NULL),
(16302,48,61,'paragraph',NULL,'These elements react with halogens to form trihalides (except TlI3).','[{"s": "These elements react with halogens to form trihalides (except TlI3).", "t": "text"}]',NULL,NULL,NULL),
(16303,48,62,'paragraph',NULL,'2E(s) + 3 X 2 (g) → 2EX 3 (s) (X = F, Cl, Br, I)','[{"s": "2E(s) + 3 X", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g) → 2EX", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(s) (X = F, Cl, Br, I)", "t": "text"}]',NULL,NULL,NULL),
