(17013,49,106,'paragraph',NULL,'7.5 How does ammonia react with a solution of Cu 2+ ?','[{"s": "7.5", "t": "text"}, {"s": "How does ammonia react with a solution of Cu", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "?", "t": "text"}]',NULL,NULL,NULL),
(17014,49,107,'heading',3,'7.4 OXIDES OF NITROGEN',NULL,NULL,NULL,NULL),
(17015,49,108,'paragraph',NULL,'Nitrogen forms a number of oxides in different oxidation states. The names, formulas, preparation and physical appearance of these oxides are given in Table 7.3.','[{"s": "Nitrogen forms a number of oxides in different oxidation states. The names, formulas, preparation and physical appearance of these oxides are given in Table 7.3.", "t": "text"}]',NULL,NULL,NULL),
