(17095,49,188,'paragraph',NULL,'In what way can it be proved that PH 3 is basic in nature?','[{"s": "In what way can it be proved that PH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "is basic in nature?", "t": "text"}]',NULL,NULL,NULL),
(17096,49,189,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17097,49,190,'paragraph',NULL,'PH 3 reacts with acids like HI to form PH 4 I which shows that it is','[{"s": "PH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "reacts with acids like HI to form PH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "I which shows that it is", "t": "text"}]',NULL,NULL,NULL),
(17098,49,191,'paragraph',NULL,'basic in nature.','[{"s": "basic in nature.", "t": "text"}]',NULL,NULL,NULL),
