(17104,49,197,'paragraph',NULL,'7.8 What happens when white phosphorus is heated with concentrated NaOH solution in an inert atmosphere of CO 2 ?','[{"s": "7.8", "t": "text"}, {"s": "What happens when white phosphorus is heated with concentrated NaOH solution in an inert atmosphere of CO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "?", "t": "text"}]',NULL,NULL,NULL),
(17105,49,198,'heading',3,'7.8 PHOSPHORUS HALIDES',NULL,NULL,NULL,NULL),
(17106,49,199,'paragraph',NULL,'Phosphorus forms two types of halides, PX 3 (X = F, Cl, Br, I) and PX 5 (X = F, Cl, Br).','[{"s": "Phosphorus forms two types of halides, PX", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(X = F, Cl, Br, I) and PX", "t": "text"}, {"s": "5", "t": "text"}, {"s": "(X = F, Cl, Br).", "t": "text"}]',NULL,NULL,NULL),
