(17120,49,213,'heading',4,'7.8.2 PHOSPHORUS PENTACHLORIDE',NULL,NULL,NULL,NULL),
(17121,49,214,'paragraph',NULL,'It has a pyramidal shape as shown, in which phosphorus is sp 3 hybridised.','[{"s": "It has a pyramidal shape as shown, in which phosphorus is sp", "t": "text"}, {"s": "3", "t": "text"}, {"s": "hybridised.", "t": "text"}]',NULL,NULL,NULL),
(17122,49,215,'paragraph',NULL,'Preparation','[{"s": "Preparation", "t": "text"}]',NULL,NULL,NULL),
(17123,49,216,'paragraph',NULL,'Phosphorus pentachloride is prepared by the reaction of white phosphorus with excess of dry chlorine.','[{"s": "Phosphorus pentachloride is prepared by the reaction of white phosphorus with excess of dry chlorine.", "t": "text"}]',NULL,NULL,NULL),
(17124,49,217,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image77.png'),
(17125,49,218,'paragraph',NULL,'It can also be prepared by the action of SO 2 Cl 2 on phosphorus.','[{"s": "It can also be prepared by the action of SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "on phosphorus.", "t": "text"}]',NULL,NULL,NULL),
