(17216,49,309,'paragraph',NULL,'H 2 S is less acidic than H 2 Te. Why?','[{"s": "H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "S is less acidic than H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "Te. Why?", "t": "text"}]',NULL,NULL,NULL),
(17217,49,310,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17218,49,311,'paragraph',NULL,'Due to the decrease in bond (E–H) dissociation enthalpy down the group, acidic character increases.','[{"s": "Due to the decrease in bond (E–H) dissociation enthalpy down the group, acidic character increases.", "t": "text"}]',NULL,NULL,NULL),
