(17221,49,314,'paragraph',NULL,'7.14 Write the order of thermal stability of the hydrides of Group 16 elements.','[{"s": "7.14", "t": "hl"}, {"s": "Write the order of thermal stability of the hydrides of Group 16 elements.", "t": "hl"}]','marked','["214208"]',NULL),
(17222,49,315,'paragraph',NULL,'7.15 Why is H 2 O a liquid and H 2 S a gas ?','[{"s": "7.15", "t": "text"}, {"s": "Why is H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O a liquid and H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "S a gas ?", "t": "text"}]',NULL,NULL,NULL),
