(17335,49,428,'heading',3,'7.17 SULPHURIC ACID',NULL,NULL,NULL,NULL),
(17336,49,429,'paragraph',NULL,'Manufacture','[{"s": "Manufacture", "t": "text"}]',NULL,NULL,NULL),
(17337,49,430,'paragraph',NULL,'Sulphuric acid is one of the most important industrial chemicals worldwide.','[{"s": "Sulphuric acid is one of the most important industrial chemicals worldwide.", "t": "text"}]',NULL,NULL,NULL),
(17338,49,431,'paragraph',NULL,'Sulphuric acid is manufactured by the Contact Process which involves three steps:','[{"s": "Sulphuric acid is manufactured by the", "t": "hl"}, {"s": "Contact Process", "t": "hl"}, {"s": "which involves three steps:", "t": "hl"}]','marked','["214259"]',NULL),
(17339,49,432,'paragraph',NULL,'(i) burning of sulphur or sulphide ores in air to generate SO 2 .','[{"s": "(i) burning of sulphur or sulphide ores in air to generate SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL);
INSERT INTO `ncert_book_blocks` (`id`, `chapter_id`, `idx`, `type`, `level`, `text`, `content`, `status`, `pyq_ids`, `image_url`) VALUES
(17340,49,433,'paragraph',NULL,'(ii) conversion of SO 2 to SO 3 by the reaction with oxygen in the presence of a catalyst (V 2 O 5 ), and','[{"s": "(ii) conversion of SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "to SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "by the reaction with oxygen in the presence of a catalyst (V", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "5", "t": "text"}, {"s": "), and", "t": "text"}]',NULL,NULL,NULL),
(17341,49,434,'paragraph',NULL,'(iii) absorption of SO 3 in H 2 SO 4 to give Oleum (H 2 S 2 O 7 ).','[{"s": "(iii) absorption of SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "in H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "to give Oleum (H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "S", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "7", "t": "text"}, {"s": ").", "t": "text"}]',NULL,NULL,NULL),
(17342,49,435,'paragraph',NULL,'A flow diagram for the manufacture of sulphuric acid is shown in (Fig. 7.7). The SO 2 produced is purified by removing dust and other impurities such as arsenic compounds.','[{"s": "A flow diagram for the manufacture of sulphuric acid is shown in (Fig. 7.7). The SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "produced is purified by removing dust and other impurities such as arsenic compounds.", "t": "text"}]',NULL,NULL,NULL),
(17343,49,436,'paragraph',NULL,'The key step in the manufacture of H 2 SO 4 is the catalytic oxidation of SO 2 with O 2 to give SO 3 in the presence of V 2 O 5 (catalyst).','[{"s": "The key step in the manufacture of H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "is the catalytic oxidation of SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "with O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "to give SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "in the presence of V", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "5", "t": "text"}, {"s": "(catalyst).", "t": "text"}]',NULL,NULL,NULL),
(17344,49,437,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image115.png'),
(17345,49,438,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image25.png'),
(17346,49,439,'paragraph',NULL,'The reaction is exothermic, reversible and the forward reaction leads to a decrease in volume. Therefore, low temperature and high pressure are the favourable conditions for maximum yield. But the temperature should not be very low otherwise rate of reaction will become slow.','[{"s": "The reaction is exothermic, reversible and the forward reaction leads to a decrease in volume. Therefore, low temperature and high pressure are the favourable conditions for maximum yield. But the temperature should not be very low otherwise rate of reaction will become slow.", "t": "text"}]',NULL,NULL,NULL),
(17347,49,440,'paragraph',NULL,'In practice, the plant is operated at a pressure of 2 bar and a temperature of 720 K. The SO 3 gas from the catalytic converter is absorbed in concentrated H 2 SO 4 to produceoleum. Dilution of oleum with water gives H 2 SO 4 of the desired concentration. In the industry two steps are carried out simultaneously to make the process a continuous one and also to reduce the cost.','[{"s": "In practice, the plant is operated at a pressure of 2 bar and a temperature of 720 K. The SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "gas from the catalytic converter is absorbed in concentrated H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "to produceoleum. Dilution of oleum with water gives H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "of the desired concentration. In the industry two steps are carried out simultaneously to make the process a continuous one and also to reduce the cost.", "t": "text"}]',NULL,NULL,NULL),
(17348,49,441,'paragraph',NULL,'SO 3 + H 2 SO 4 → H 2 S 2 O 7','[{"s": "SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "→ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "S", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "7", "t": "text"}]',NULL,NULL,NULL),
(17349,49,442,'paragraph',NULL,'(Oleum) 2','[{"s": "(Oleum) 2", "t": "hl"}]','marked','["214213", "214258"]',NULL),
(17350,49,443,'paragraph',NULL,'The sulphuric acid obtained by Contact process is 96-98% pure.','[{"s": "The sulphuric acid obtained by Contact process is 96-98% pure.", "t": "hl"}]','marked','["214289"]',NULL),
(17351,49,444,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image63.png'),
(17883,50,238,'paragraph',NULL,'0 –1 –1 0','[{"s": "0 –1 –1 0", "t": "text"}]',NULL,NULL,NULL),
(17352,49,445,'paragraph',NULL,'Fig. 7.7: Flow diagram for the manufacture of sulphuric acid','[{"s": "Fig. 7.7: Flow diagram for the manufacture of sulphuric acid", "t": "text"}]',NULL,NULL,NULL),
(17353,49,446,'paragraph',NULL,'Properties','[{"s": "Properties", "t": "text"}]',NULL,NULL,NULL),
(17354,49,447,'paragraph',NULL,'Sulphuric acid is a colourless, dense, oily liquid with a specific gravity of 1.84 at 298 K. The acid freezes at 283 K and boils at 611 K. It dissolves in water with the evolution of a large quantity of heat. Hence, care must be taken while preparing sulphuric acid solution from concentrated sulphuric acid. The concentrated acid must be added slowly into water with constant stirring.','[{"s": "Sulphuric acid is a colourless, dense, oily liquid with a specific gravity of 1.84 at 298 K. The acid freezes at 283 K and boils at 611 K. It dissolves in water with the evolution of a large quantity of heat. Hence, care must be taken while preparing sulphuric acid solution from concentrated sulphuric acid. The concentrated acid must be added slowly into water with constant stirring.", "t": "text"}]',NULL,NULL,NULL),
(17355,49,448,'paragraph',NULL,'The chemical reactions of sulphuric acid are as a result of the following characteristics: (a) low volatility (b) strong acidic character (c) strong affinity for water and (d) ability to act as an oxidising agent. In aqueous solution, sulphuric acid ionises in two steps.','[{"s": "The chemical reactions of sulphuric acid are as a result of the following characteristics: (a) low volatility (b) strong acidic character (c) strong affinity for water and (d) ability to act as an oxidising agent.", "t": "hl"}, {"s": "In aqueous solution, sulphuric acid ionises in two steps.", "t": "text"}]','marked','["214297"]',NULL),
(17356,49,449,'paragraph',NULL,'H 2 SO 4 (aq) + H 2 O(l) → H 3 O + (aq) + HSO 4 – (aq); P_Block_Elements_Group_15_to_18-image44.png = very large ( P_Block_Elements_Group_15_to_18-image44.png >10)','[{"s": "H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(aq) + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O(l) → H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "(aq) + HSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq);", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image44.png", "t": "img", "alt": ""}, {"s": "= very large (", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image44.png", "t": "img", "alt": ""}, {"s": ">10)", "t": "text"}]',NULL,NULL,NULL),
(17357,49,450,'paragraph',NULL,'HSO 4 – (aq) + H 2 O(l) → H 3 O + (aq) + SO 4 2- (aq) ; P_Block_Elements_Group_15_to_18-image26.png = 1.2 × 10 –2','[{"s": "HSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq) + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O(l) → H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "(aq) + SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "2-", "t": "text"}, {"s": "(aq) ;", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image26.png", "t": "img", "alt": ""}, {"s": "= 1.2 × 10", "t": "text"}, {"s": "–2", "t": "text"}]',NULL,NULL,NULL),
(17358,49,451,'paragraph',NULL,'The larger value of P_Block_Elements_Group_15_to_18-image44.png ( P_Block_Elements_Group_15_to_18-image44.png >10) means that H 2 SO 4 is largely dissociated into H + and HSO 4 – . Greater the value of dissociation constant (K a ), the stronger is the acid.','[{"s": "The larger value of", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image44.png", "t": "img", "alt": ""}, {"s": "(", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image44.png", "t": "img", "alt": ""}, {"s": ">10) means that H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "is largely dissociated into H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "and HSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "–", "t": "text"}, {"s": ". Greater the value of dissociation constant (K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "), the stronger is the acid.", "t": "text"}]',NULL,NULL,NULL),
(17359,49,452,'paragraph',NULL,'The acid forms two series of salts: normal sulphates (such as sodium sulphate and copper sulphate) and acid sulphates (e.g., sodium hydrogen sulphate).','[{"s": "The acid forms two series of salts: normal sulphates (such as sodium sulphate and copper sulphate) and acid sulphates (e.g., sodium hydrogen sulphate).", "t": "text"}]',NULL,NULL,NULL),
(17360,49,453,'paragraph',NULL,'Sulphuric acid, because of its low volatility can be used to manufacture more volatile acids from their corresponding salts.','[{"s": "Sulphuric acid, because of its low volatility can be used to manufacture more volatile acids from their corresponding salts.", "t": "text"}]',NULL,NULL,NULL),
(17361,49,454,'paragraph',NULL,'2 MX + H 2 SO 4 → 2 HX + M 2 SO 4 (X = F, Cl, NO 3 )','[{"s": "2 MX + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "→ 2 HX + M", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(X = F, Cl, NO", "t": "text"}, {"s": "3", "t": "text"}, {"s": ")", "t": "text"}]',NULL,NULL,NULL),
(17362,49,455,'paragraph',NULL,'(M = Metal)','[{"s": "(M = Metal)", "t": "text"}]',NULL,NULL,NULL),
(17363,49,456,'paragraph',NULL,'Concentrated sulphuric acid is a strong dehydrating agent. Many wet gases can be dried by passing them through sulphuric acid, provided the gases do not react with the acid. Sulphuric acid removes water from organic compounds; it is evident by its charring action on carbohydrates.','[{"s": "Concentrated sulphuric acid is a strong dehydrating agent. Many wet gases can be dried by passing them through sulphuric acid, provided the gases do not react with the acid. Sulphuric acid removes water from organic compounds; it is evident by its charring action on carbohydrates.", "t": "text"}]',NULL,NULL,NULL),
(17364,49,457,'paragraph',NULL,'C 12 H 22 O 11 P_Block_Elements_Group_15_to_18-image49.png 12C + 11H 2 O','[{"s": "C", "t": "text"}, {"s": "12", "t": "text"}, {"s": "H", "t": "text"}, {"s": "22", "t": "text"}, {"s": "O", "t": "text"}, {"s": "11", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image49.png", "t": "img", "alt": ""}, {"s": "12C + 11H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17365,49,458,'paragraph',NULL,'Hot concentrated sulphuric acid is a moderately strong oxidising agent. In this respect, it is intermediate between phosphoric and nitric acids. Both metals and non-metals are oxidised by concentrated sulphuric acid, which is reduced to SO 2 .','[{"s": "Hot concentrated sulphuric acid is a moderately strong oxidising agent. In this respect, it is intermediate between phosphoric and nitric acids. Both metals and non-metals are oxidised by concentrated sulphuric acid, which is reduced to SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17366,49,459,'paragraph',NULL,'Cu + 2 H 2 SO 4 (conc.) → CuSO 4 + SO 2 + 2H 2 O','[{"s": "Cu + 2 H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(conc.) → CuSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17367,49,460,'paragraph',NULL,'S + 2H 2 SO 4 (conc.) → 3SO 2 + 2H 2 O','[{"s": "S + 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(conc.) → 3SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17368,49,461,'paragraph',NULL,'C + 2H 2 SO 4 (conc.) → CO 2 + 2 SO 2 + 2 H 2 O','[{"s": "C + 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(conc.) → CO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2 SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2 H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17369,49,462,'paragraph',NULL,'Uses : Sulphuric acid is a very important industrial chemical. A nation’s industrial strength can be judged by the quantity of sulphuric acid it produces and consumes. It is needed for the manufacture of hundreds of other compounds and also in many industrial processes. The bulk of sulphuric acid produced is used in the manufacture of fertilisers (e.g., ammonium sulphate, superphosphate). Other uses are in: (a) petroleum refining (b) manufacture of pigments, paints and dyestuff intermediates (c) detergent industry (d) metallurgical applications (e.g., cleansing metals before enameling, electroplating and galvanising (e) storage batteries (f) in the manufacture of nitrocellulose products and (g) as a laboratory reagent.','[{"s": "Uses", "t": "text"}, {"s": ": Sulphuric acid is a very important industrial chemical. A nation’s industrial strength can be judged by the quantity of sulphuric acid it produces and consumes. It is needed for the manufacture of hundreds of other compounds and also in many industrial processes. The bulk of sulphuric acid produced is used in the manufacture of fertilisers (e.g., ammonium sulphate, superphosphate). Other uses are in: (a) petroleum refining (b) manufacture of pigments, paints and dyestuff intermediates (c) detergent industry (d) metallurgical applications (e.g., cleansing metals before enameling, electroplating and galvanising (e) storage batteries (f) in the manufacture of nitrocellulose products and (g) as a laboratory reagent.", "t": "text"}]',NULL,NULL,NULL),
(17370,49,463,'paragraph',NULL,'Example 7.13','[{"s": "Example 7.13", "t": "text"}]',NULL,NULL,NULL),
(17371,49,464,'paragraph',NULL,'What happens when','[{"s": "What happens when", "t": "text"}]',NULL,NULL,NULL),
(17372,49,465,'paragraph',NULL,'(i) Concentrated H 2 SO 4 is added to calcium fluoride','[{"s": "(i) Concentrated H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "is added to calcium fluoride", "t": "text"}]',NULL,NULL,NULL),
(17373,49,466,'paragraph',NULL,'(ii) SO 3 is passed through water?','[{"s": "(ii) SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "is passed through water?", "t": "text"}]',NULL,NULL,NULL),
(17374,49,467,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17375,49,468,'paragraph',NULL,'(i) It forms hydrogen fluoride','[{"s": "(i) It forms hydrogen fluoride", "t": "text"}]',NULL,NULL,NULL),
(17376,49,469,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image121.png'),
(17377,49,470,'paragraph',NULL,'(ii) It dissolves SO 3 to give H 2 SO 4 .','[{"s": "(ii) It dissolves SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "to give H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17378,49,471,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image64.png'),
(17379,49,472,'paragraph',NULL,'Intext Questions','[{"s": "Intext Questions", "t": "text"}]',NULL,NULL,NULL),
(17380,49,473,'paragraph',NULL,'7.23 Mention three areas in which H 2 SO 4 plays an important role.','[{"s": "7.23", "t": "text"}, {"s": "Mention three areas in which H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "plays an important role.", "t": "text"}]',NULL,NULL,NULL),
(17381,49,474,'paragraph',NULL,'7.24 Write the conditions to maximise the yield of H 2 SO 4 by Contact process.','[{"s": "7.24", "t": "text"}, {"s": "Write the conditions to maximise the yield of H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "by Contact process.", "t": "text"}]',NULL,NULL,NULL),
(17382,49,475,'paragraph',NULL,'7.25 Why is K a 2 = K a 1 for H 2 SO 4 in water ?','[{"s": "7.25", "t": "text"}, {"s": "Why is K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "2", "t": "text"}, {"s": "= K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "1", "t": "text"}, {"s": "for H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "in water ?", "t": "text"}]',NULL,NULL,NULL),
(17383,49,476,'heading',3,'7.18 GROUP 17 ELEMENTS',NULL,NULL,NULL,NULL),
(17384,49,477,'paragraph',NULL,'Fluorine, chlorine, bromine, iodine, astatine and tennessine are members of Group 17. These are collectively known as the halogens (Greek halo means salt and genesmeans born i.e., salt producers). The halogens are highly reactive non-metallic elements. Like Groups 1 and 2, the elements of Group 17 show great similarity amongst themselves. That much similarity is not found in the elements of other groups of the periodic table. Also, there is a regular gradation in their physical and chemical properties. Astatine and tennessine are radioactive elements.','[{"s": "Fluorine, chlorine, bromine, iodine, astatine and tennessine are members of Group 17. These are collectively known as the", "t": "text"}, {"s": "halogens", "t": "text"}, {"s": "(Greek halo means salt and genesmeans born i.e., salt producers). The halogens are highly reactive non-metallic elements. Like Groups 1 and 2, the elements of Group 17 show great similarity amongst themselves. That much similarity is not found in the elements of other groups of the periodic table. Also, there is a regular gradation in their physical and chemical properties. Astatine and tennessine are radioactive elements.", "t": "text"}]',NULL,NULL,NULL),
(17385,49,478,'heading',4,'7.18.1 OCCURRENCE',NULL,NULL,NULL,NULL),
(28998,71,131,'paragraph',NULL,'R = – Nuclei-image97.png','[{"s": "R", "t": "text"}, {"s": "= –", "t": "text"}, {"s": "Nuclei-image97.png", "t": "img", "alt": ""}]',NULL,NULL,NULL),
(17386,49,479,'paragraph',NULL,'Fluorine and chlorine are fairly abundant while bromine and iodine less so. Fluorine is present mainly as insoluble fluorides (fluorspar CaF 2 , cryolite Na 3 AlF 6 and fluoroapatite 3Ca 3 (PO 4 ) 2 .CaF 2 ) and small quantities are present in soil, river water plants and bones and teeth of animals. Sea water contains chlorides, bromides and iodides of sodium, potassium, magnesium and calcium, but is mainly sodium chloride solution (2.5% by mass). The deposits of dried up seas contain these compounds, e.g., sodium chloride and carnallite, KCl.MgCl 2 .6H 2 O. Certain forms of marine life contain iodine in their systems; various seaweeds, for example, contain upto 0.5% of iodine and Chile saltpetre contains upto 0.2% of sodium iodate.','[{"s": "Fluorine and chlorine are fairly abundant while bromine and iodine less so. Fluorine is present mainly as insoluble fluorides (fluorspar CaF", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", cryolite Na", "t": "text"}, {"s": "3", "t": "text"}, {"s": "AlF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "and fluoroapatite 3Ca", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(PO", "t": "text"}, {"s": "4", "t": "text"}, {"s": ")", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".CaF", "t": "text"}, {"s": "2", "t": "text"}, {"s": ")", "t": "text"}, {"s": "and small quantities are present in soil, river water plants and bones and teeth of animals. Sea water contains chlorides, bromides and iodides of sodium, potassium, magnesium and calcium, but is mainly sodium chloride solution (2.5% by mass). The deposits of dried up seas contain these compounds, e.g., sodium chloride and carnallite, KCl.MgCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".6H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O. Certain forms of marine life contain iodine in their systems; various seaweeds, for example, contain upto 0.5% of iodine and Chile saltpetre contains upto 0.2% of sodium iodate.", "t": "text"}]',NULL,NULL,NULL),
(17387,49,480,'paragraph',NULL,'Here important atomic and physical properties of Group 17 elements other than tennessine are given along with their electronic configurations [Table 7.8, page 198]. Tennessine is a synthetic radioactive element. Its symbol is Ts, atomic number 117, atomic mass 294 and electronic configuration [Rn] 5f 14 6d 10 7s 2 7p 5 . Only very small amount of the element could be prepared. Also its half life is in milliseconds only. That is why its chemistry could not be established.','[{"s": "Here important atomic and physical properties of Group 17 elements other than tennessine are given along with their electronic configurations [Table 7.8, page 198]. Tennessine is a synthetic radioactive element. Its symbol is Ts, atomic number 117, atomic mass 294 and electronic configuration [Rn] 5f", "t": "text"}, {"s": "14", "t": "text"}, {"s": "6d", "t": "text"}, {"s": "10", "t": "text"}, {"s": "7s", "t": "text"}, {"s": "2", "t": "text"}, {"s": "7p", "t": "text"}, {"s": "5", "t": "text"}, {"s": ". Only very small amount of the element could be prepared. Also its half life is in milliseconds only. That is why its chemistry could not be established.", "t": "text"}]',NULL,NULL,NULL),
(17388,49,481,'paragraph',NULL,'Table 7.8: Atomic and Physical Properties of Halogens','[{"s": "Table 7.8: Atomic and Physical Properties of Halogens", "t": "text"}]',NULL,NULL,NULL),
(17389,49,482,'image',NULL,'7h',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image70.png'),
(17390,49,483,'paragraph',NULL,'The trends of some of the atomic, physical and chemical properties are discussed below.','[{"s": "The trends of some of the atomic, physical and chemical properties are discussed below.", "t": "text"}]',NULL,NULL,NULL),
(17391,49,484,'heading',4,'7.18.2 ELECTRONIC CONFIGURATION',NULL,NULL,NULL,NULL),
(17392,49,485,'paragraph',NULL,'All these elements have seven electrons in their outermost shell (ns 2 np 5 ) which is one electron short of the next noble gas.','[{"s": "All these elements have seven electrons in their outermost shell (ns", "t": "text"}, {"s": "2", "t": "text"}, {"s": "np", "t": "text"}, {"s": "5", "t": "text"}, {"s": ") which is one electron short of the next noble gas.", "t": "text"}]',NULL,NULL,NULL),
(17393,49,486,'heading',4,'7.18.3 ATOMIC AND IONIC RADII',NULL,NULL,NULL,NULL),
(17394,49,487,'paragraph',NULL,'The halogens have the smallest atomic radii in their respective periods due to maximum effective nuclear charge. The atomic radius of fluorine like the other elements of second period is extremely small. Atomic and ionic radii increase from fluorine to iodine due to increasing number of quantum shells.','[{"s": "The halogens have the smallest atomic radii in their respective periods due to maximum effective nuclear charge. The atomic radius of fluorine like the other elements of second period is extremely small. Atomic and ionic radii increase from fluorine to iodine due to increasing number of quantum shells.", "t": "text"}]',NULL,NULL,NULL),
(17395,49,488,'heading',4,'7.18.4 IONISATION ENTHALPY',NULL,NULL,NULL,NULL),
(17396,49,489,'paragraph',NULL,'They have little tendency to lose electron. Thus they have very high ionisation enthalpy. Due to increase in atomic size, ionisation enthalpy decreases down the group.','[{"s": "They have little tendency to lose electron. Thus they have very high ionisation enthalpy. Due to increase in atomic size, ionisation enthalpy decreases down the group.", "t": "text"}]',NULL,NULL,NULL),
(17397,49,490,'heading',4,'7.18.5 ELECTRON GAIN ENTHALPY',NULL,NULL,NULL,NULL),
(17398,49,491,'paragraph',NULL,'Halogens have maximum negative electron gain enthalpy in the corresponding periods. This is due to the fact that the atoms of these elements have only one electron less than stable noble gas configurations. Electron gain enthalpy of the elements of the group becomes less negative down the group. However, the negative electron gain enthalpy of fluorine is less than that of chlorine. It is due to small size of fluorine atom. As a result, there are strong interelectronic repulsions in the relatively small 2p orbitals of fluorine and thus, the incoming electron does not experience much attraction.','[{"s": "Halogens have maximum negative electron gain enthalpy in the corresponding periods. This is due to the fact that the atoms of these elements have only one electron less than stable noble gas configurations. Electron gain enthalpy of the elements of the group becomes less negative down the group. However, the negative electron gain enthalpy of fluorine is less than that of chlorine. It is due to small size of fluorine atom. As a result, there are strong interelectronic repulsions in the relatively small 2p orbitals of fluorine and thus, the incoming electron does not experience much attraction.", "t": "text"}]',NULL,NULL,NULL),
(17399,49,492,'heading',4,'7.18.6 ELECTRONEGATIVITY',NULL,NULL,NULL,NULL),
(17400,49,493,'paragraph',NULL,'They have very high electronegativity. The electronegativity decreases down the group. Fluorine is the most electronegative element in the periodic table.','[{"s": "They have very high electronegativity. The electronegativity decreases down the group. Fluorine is the most electronegative element in the periodic table.", "t": "text"}]',NULL,NULL,NULL),
(17401,49,494,'paragraph',NULL,'Example 7.14','[{"s": "Example 7.14", "t": "text"}]',NULL,NULL,NULL),
(17402,49,495,'paragraph',NULL,'Halogens have maximum negative electron gain enthalpy in the respective periods of the periodic table. Why?','[{"s": "Halogens have maximum negative electron gain enthalpy in the respective periods of the periodic table. Why?", "t": "text"}]',NULL,NULL,NULL),
(17403,49,496,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17404,49,497,'paragraph',NULL,'Halogens have the smallest size in their respective periods and therefore high effective nuclear charge. As a consequence, they readily accept one electron to acquire noble gas electronic configuration.','[{"s": "Halogens have the smallest size in their respective periods and therefore high effective nuclear charge. As a consequence, they readily accept one electron to acquire noble gas electronic configuration.", "t": "text"}]',NULL,NULL,NULL),
(17405,49,498,'heading',4,'7.18.7 PHYSICAL PROPERTIES',NULL,NULL,NULL,NULL),
(17406,49,499,'paragraph',NULL,'Halogens display smooth variations in their physical properties. Fluorine and chlorine are gases, bromine is a liquid and iodine is a solid. Their melting and boiling points steadily increase with atomic number. All halogens are coloured. This is due to absorption of radiations in visible region which results in the excitation of outer electrons to higher energy level. By absorbing different quanta of radiation, they display different colours. For example, F 2 , has yellow, Cl 2 , greenish yellow, Br 2 , red and I 2 , violet colour. Fluorine and chlorine react with water. Bromine and iodine are only sparingly soluble in water but are soluble in various organic solvents such as chloroform, carbon tetrachloride, carbon disulphide and hydrocarbons to give coloured solutions.','[{"s": "Halogens display smooth variations in their physical properties. Fluorine and chlorine are gases, bromine is a liquid and iodine is a solid. Their melting and boiling points steadily increase with atomic number. All halogens are coloured. This is due to absorption of radiations in visible region which results in the excitation of outer electrons to higher energy level. By absorbing different quanta of radiation, they display different colours. For example, F", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", has yellow, Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", greenish yellow, Br", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", red and I", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", violet colour. Fluorine and chlorine react with water. Bromine and iodine are only sparingly soluble in water but are soluble in various organic solvents such as chloroform, carbon tetrachloride, carbon disulphide and hydrocarbons to give coloured solutions.", "t": "text"}]',NULL,NULL,NULL),
(17407,49,500,'paragraph',NULL,'One curious anomaly we notice from Table 7.8 is the smaller enthalpy of dissociation of F 2 compared to that of Cl 2 whereas X-X bond dissociation enthalpies from chlorine onwards show the expected trend: Cl – Cl > Br – Br > I – I. 3 A reason for this anomaly is the relatively large electron-electron repulsion among the lone pairs in F 2 molecule where they are much closer to each other than in case of Cl 2 .','[{"s": "One curious anomaly we notice from Table 7.8 is the smaller enthalpy of dissociation of F", "t": "hl"}, {"s": "2", "t": "hl"}, {"s": "compared to that of Cl", "t": "hl"}, {"s": "2", "t": "hl"}, {"s": "whereas X-X bond dissociation enthalpies from chlorine onwards show the expected trend: Cl – Cl > Br – Br > I – I.", "t": "hl"}, {"s": "3", "t": "hl"}, {"s": "A reason for this anomaly is the relatively large electron-electron repulsion among the lone pairs in F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "molecule where they are much closer to each other than in case of Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]','marked','["214216", "214264", "214300"]',NULL),
(17408,49,501,'paragraph',NULL,'Example 7.15','[{"s": "Example 7.15", "t": "text"}]',NULL,NULL,NULL),
(17409,49,502,'paragraph',NULL,'Although electron gain enthalpy of fluorine is less negative as compared to chlorine, fluorine is a stronger oxidising agent than chlorine. Why?','[{"s": "Although electron gain enthalpy of fluorine is less negative as compared to chlorine, fluorine is a stronger oxidising agent than chlorine. Why?", "t": "hl"}]','marked','["214301"]',NULL),
(17410,49,503,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17411,49,504,'paragraph',NULL,'It is due to','[{"s": "It is due to", "t": "text"}]',NULL,NULL,NULL),
(17412,49,505,'paragraph',NULL,'(i) low enthalpy of dissociation of F-F bond (Table 7.8).','[{"s": "(i) low enthalpy of dissociation of F-F bond (Table 7.8).", "t": "text"}]',NULL,NULL,NULL),
(17413,49,506,'paragraph',NULL,'(ii) high hydration enthalpy of F – (Table 7.8).','[{"s": "(ii) high hydration enthalpy of F", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(Table 7.8).", "t": "text"}]',NULL,NULL,NULL),
(17414,49,507,'heading',4,'7.18.8 CHEMICAL PROPERTIES',NULL,NULL,NULL,NULL),
(17415,49,508,'paragraph',NULL,'Oxidation states and trends in chemical reactivity','[{"s": "Oxidation states and trends in chemical reactivity", "t": "text"}]',NULL,NULL,NULL),
(17416,49,509,'paragraph',NULL,'All the halogens exhibit –1 oxidation state. However, chlorine, bromine and iodine exhibit + 1, + 3, + 5 and + 7 oxidation states also as explained below:','[{"s": "All the halogens exhibit –1 oxidation state. However, chlorine, bromine and iodine exhibit + 1, + 3, + 5 and + 7 oxidation states also as explained below:", "t": "text"}]',NULL,NULL,NULL),
(17417,49,510,'image',NULL,'7i',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image55.png'),
(17418,49,511,'paragraph',NULL,'The higher oxidation states of chlorine, bromine and iodine are realised mainly when the halogens are in combination with the small and highly electronegative fluorine and oxygen atoms. e.g., in interhalogens, oxides and oxoacids. The oxidation states of +4 and +6 occur in the oxides and oxoacids of chlorine and bromine. The fluorine atom has no d orbitals in its valence shell and therefore cannot expand its octet. Being the most electronegative, it exhibits only –1 oxidation state.','[{"s": "The higher oxidation states of chlorine, bromine and iodine are realised mainly when the halogens are in combination with the small and highly electronegative fluorine and oxygen atoms. e.g., in interhalogens, oxides and oxoacids. The oxidation states of +4 and +6 occur in the oxides and oxoacids of chlorine and bromine. The fluorine atom has no d orbitals in its valence shell and therefore cannot expand its octet. Being the most electronegative, it exhibits only –1 oxidation state.", "t": "text"}]',NULL,NULL,NULL),
(17419,49,512,'paragraph',NULL,'All the halogens are highly reactive. They react with metals and non-metals to form halides. The reactivity of the halogens decreases down the group.','[{"s": "All the halogens are highly reactive. They react with metals and non-metals to form halides. The reactivity of the halogens decreases down the group.", "t": "text"}]',NULL,NULL,NULL),
(17884,50,239,'paragraph',NULL,'Cl 2 (g) + 2I – (aq) → 2Cl – (aq) + I 2 (s) (8.42b)','[{"s": "Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g) + 2I", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq)", "t": "text"}, {"s": "→", "t": "text"}, {"s": "2Cl", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq) + I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(s) (8.42b)", "t": "text"}]',NULL,NULL,NULL),
(17420,49,513,'paragraph',NULL,'The ready acceptance of an electron is the reason for the strong oxidising nature of halogens. F 2 is the strongest oxidising halogen and it oxidises other halide ions in solution or even in the solid phase. 2 In general, a halogen oxidises halide ions of higher atomic number.','[{"s": "The ready acceptance of an electron is the reason for the strong oxidising nature of halogens. F", "t": "hl"}, {"s": "2", "t": "hl"}, {"s": "is the strongest oxidising halogen and it oxidises other halide ions in solution or even in the solid phase.", "t": "hl"}, {"s": "2", "t": "text"}, {"s": "In general, a halogen oxidises halide ions of higher atomic number.", "t": "text"}]','marked','["214261", "214302"]',NULL),
(17421,49,514,'paragraph',NULL,'F 2 + 2X – → 2F – + X 2 (X = Cl, Br or I)','[{"s": "F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2X", "t": "text"}, {"s": "–", "t": "text"}, {"s": "→ 2F", "t": "text"}, {"s": "–", "t": "text"}, {"s": "+ X", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(X = Cl, Br or I)", "t": "text"}]',NULL,NULL,NULL),
(17422,49,515,'paragraph',NULL,'Cl 2 + 2X – → 2Cl – + X 2 (X = Br or I)','[{"s": "Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2X", "t": "text"}, {"s": "–", "t": "text"}, {"s": "→ 2Cl", "t": "text"}, {"s": "–", "t": "text"}, {"s": "+ X", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(X = Br or I)", "t": "text"}]',NULL,NULL,NULL),
(17423,49,516,'paragraph',NULL,'Br 2 + 2I – → 2Br – + I 2','[{"s": "Br", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2I", "t": "text"}, {"s": "–", "t": "text"}, {"s": "→ 2Br", "t": "text"}, {"s": "–", "t": "text"}, {"s": "+ I", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17424,49,517,'paragraph',NULL,'The decreasing oxidising ability of the halogens in aqueous solution down the group is evident from their standard electrode potentials (Table 7.8) which are dependent on the parameters indicated below:','[{"s": "The decreasing oxidising ability of the halogens in aqueous solution down the group is evident from their standard electrode potentials (Table 7.8) which are dependent on the parameters indicated below:", "t": "text"}]',NULL,NULL,NULL),
(17425,49,518,'image',NULL,'rxn',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image23.png'),
(17426,49,519,'paragraph',NULL,'The relative oxidising power of halogens can further be illustrated by their reactions with water. Fluorine oxidises water to oxygen whereas chlorine and bromine react with water to form corresponding hydrohalic and hypohalous acids. The reaction of iodine with water is non-spontaneous. In fact, I – can be oxidised by oxygen in acidic medium; just the reverse of the reaction observed with fluorine.','[{"s": "The relative oxidising power of halogens can further be illustrated by their reactions with water. Fluorine oxidises water to oxygen whereas chlorine and bromine react with water to form corresponding hydrohalic and hypohalous acids. The reaction of iodine with water is non-spontaneous. In fact, I", "t": "text"}, {"s": "–", "t": "text"}, {"s": "can be oxidised by oxygen in acidic medium; just the reverse of the reaction observed with fluorine.", "t": "text"}]',NULL,NULL,NULL),
(17427,49,520,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image122.png'),
(17428,49,521,'paragraph',NULL,'Anomalous behaviour of fluorine','[{"s": "Anomalous behaviour of fluorine", "t": "text"}]',NULL,NULL,NULL),
(17429,49,522,'paragraph',NULL,'Like other elements of p-block present in second period of the periodic table, fluorine is anomalous in many properties. For example, ionisation enthalpy, electronegativity, and electrode potentials are all higher for fluorine than expected from the trends set by other halogens. Also, ionic and covalent radii, m.p. and b.p., enthalpy of bond dissociation and electron gain enthalpy are quite lower than expected. The anomalous behaviour of fluorine is due to its small size, highest electronegativity, low F-F bond dissociation enthalpy, and non availability of d orbitals in valence shell.','[{"s": "Like other elements of p-block present in second period of the periodic table, fluorine is anomalous in many properties. For example, ionisation enthalpy, electronegativity, and electrode potentials are all higher for fluorine than expected from the trends set by other halogens. Also, ionic and covalent radii, m.p. and b.p., enthalpy of bond dissociation and electron gain enthalpy are quite lower than expected. The anomalous behaviour of fluorine is due to its small size, highest electronegativity, low F-F bond dissociation enthalpy, and non availability of d orbitals in valence shell.", "t": "text"}]',NULL,NULL,NULL),
(17430,49,523,'paragraph',NULL,'Most of the reactions of fluorine are exothermic (due to the small and strong bond formed by it with other elements). It forms only one oxoacid while other halogens form a number of oxoacids. Hydrogen fluoride is a liquid (b.p. 293 K) due to strong hydrogen bonding. Hydrogen bond is formed in HF due to small size and high electronegativity of fluorine. Other hydrogen halides which have bigger size and less electronegativity are gases.','[{"s": "Most of the reactions of fluorine are exothermic (due to the small and strong bond formed by it with other elements). It forms only one oxoacid while other halogens form a number of oxoacids.", "t": "text"}, {"s": "Hydrogen fluoride is a liquid (b.p. 293 K) due to strong hydrogen bonding.", "t": "hl"}, {"s": "Hydrogen bond is formed in HF due to small size and high electronegativity of fluorine. Other hydrogen halides which have bigger size and less electronegativity are gases.", "t": "text"}]','marked','["214260"]',NULL),
(17431,49,524,'paragraph',NULL,'(i) Reactivity towards hydrogen: They all react with hydrogen to give hydrogen halides but affinity for hydrogen decreases from fluorine to iodine. Hydrogen halides dissolve in water to form hydrohalic acids. Some of the properties of hydrogen halides are given in Table 7.9. The acidic strength of these acids varies in the order: HF < HCl < HBr < HI. The stability of these halides decreases down the group due to decrease in bond (H–X) dissociation enthalpy in the order: H–F > H–Cl > H–Br > H–I.','[{"s": "(i) Reactivity towards hydrogen: They all react with hydrogen to give hydrogen halides but affinity for hydrogen decreases from fluorine to iodine. Hydrogen halides dissolve in water to form hydrohalic acids. Some of the properties of hydrogen halides are given in Table 7.9. The acidic strength of these acids varies in the order: HF < HCl < HBr < HI.", "t": "text"}, {"s": "The stability of these halides decreases down the group due to decrease in bond (H–X) dissociation enthalpy in the order: H–F > H–Cl > H–Br > H–I.", "t": "text"}]',NULL,NULL,NULL),
(17432,49,525,'paragraph',NULL,'Table 7.9: Properties of Hydrogen Halides 2','[{"s": "Table 7.9: Properties of Hydrogen Halides 2", "t": "hl"}]','marked','["214283", "214304"]',NULL),
(17433,49,526,'image',NULL,'7j',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image118.png'),
(17434,49,527,'paragraph',NULL,'(ii) Reactivity towards oxygen: Halogens form many oxides with oxygen but most of them are unstable. Fluorine forms two oxides OF 2 and O 2 F 2 . However, only OF 2 is thermally stable at 298 K. These oxides are essentially oxygen fluorides because of the higher electronegativity of fluorine than oxygen. Both are strong fluorinating agents. O 2 F 2 oxidises plutonium to PuF 6 and the reaction is used in removing plutonium as PuF 6 from spent nuclear fuel.','[{"s": "(ii) Reactivity towards oxygen: Halogens form many oxides with oxygen but most of them are unstable. Fluorine forms two oxides OF", "t": "text"}, {"s": "2", "t": "text"}, {"s": "and O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "F", "t": "text"}, {"s": "2", "t": "text"}, {"s": ". However, only OF", "t": "text"}, {"s": "2", "t": "text"}, {"s": "is thermally stable at 298 K.", "t": "text"}, {"s": "These oxides are essentially oxygen fluorides because of the higher electronegativity of fluorine than oxygen.", "t": "hl"}, {"s": "Both are strong fluorinating agents. O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "oxidises plutonium to PuF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "and the reaction is used in removing plutonium as PuF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "from spent nuclear fuel.", "t": "text"}]','marked','["214275"]',NULL),
(17435,49,528,'paragraph',NULL,'Chlorine, bromine and iodine form oxides in which the oxidation states of these halogens range from +1 to +7. A combination of kinetic and thermodynamic factors lead to the generally decreasing order of stability of oxides formed by halogens, I > Cl > Br. Higher stability of oxides of iodine is due to greater polarisability of bond between iodine and oxygen. In the case of chlorine, multiple bond formation between chlorine and oxygen takes place due to availability of d–orbitals. This leads to increase in stability. Bromine lacks both the characteristics hence stability of oxides of bromine is least. The higher oxides of halogens tend to be more stable than the lower ones.','[{"s": "Chlorine, bromine and iodine form oxides in which the oxidation states of these halogens range from +1 to +7. A combination of kinetic and thermodynamic factors lead to the generally decreasing order of stability of oxides formed by halogens, I > Cl > Br. Higher stability of oxides of iodine is due to greater polarisability of bond between iodine and oxygen. In the case of chlorine, multiple bond formation between chlorine and oxygen takes place due to availability of d–orbitals. This leads to increase in stability. Bromine lacks both the characteristics hence stability of oxides of bromine is least. The higher oxides of halogens tend to be more stable than the lower ones.", "t": "text"}]',NULL,NULL,NULL),
(17436,49,529,'paragraph',NULL,'Chlorine oxides, Cl 2 O, ClO 2 , Cl 2 O 6 and Cl 2 O 7 are highly reactive oxidising agents and tend to explode. ClO 2 is used as a bleaching agent for paper pulp and textiles and in water treatment.','[{"s": "Chlorine oxides, Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O, ClO", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "6", "t": "text"}, {"s": "and Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "7", "t": "text"}, {"s": "are highly reactive oxidising agents and tend to explode. ClO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "is used as a bleaching agent for paper pulp and textiles and in water treatment.", "t": "text"}]',NULL,NULL,NULL),
(17437,49,530,'paragraph',NULL,'The bromine oxides, Br 2 O, BrO 2 , BrO 3 are the least stable halogen oxides (middle row anomally) and exist only at low temperatures. They are very powerful oxidising agents.','[{"s": "The bromine oxides, Br", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O, BrO", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", BrO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "are the least stable halogen oxides (middle row anomally) and exist only at low temperatures. They are very powerful oxidising agents.", "t": "text"}]',NULL,NULL,NULL),
(17438,49,531,'paragraph',NULL,'The iodine oxides, I 2 O 4 , I 2 O 5 , I 2 O 7 are insoluble solids and decompose on heating. I 2 O 5 is a very good oxidising agent and is used in the estimation of carbon monoxide.','[{"s": "The iodine oxides, I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "4", "t": "text"}, {"s": ", I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "5", "t": "text"}, {"s": ", I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "7", "t": "text"}, {"s": "are insoluble solids and decompose on heating. I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "5", "t": "text"}, {"s": "is a very good oxidising agent and is used in the estimation of carbon monoxide.", "t": "text"}]',NULL,NULL,NULL),
(17439,49,532,'paragraph',NULL,'(iii) Reactivity towards metals: Halogens react with metals to form metal halides. For example, bromine reacts with magnesium to give magnesium bromide.','[{"s": "(iii) Reactivity towards metals: Halogens react with metals to form metal halides. For example, bromine reacts with magnesium to give magnesium bromide.", "t": "text"}]',NULL,NULL,NULL),
(17440,49,533,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image37.png'),
(17441,49,534,'paragraph',NULL,'The ionic character of the halides decreases in the order MF > MCl > MBr > MI where M is a monovalent metal. If a metal exhibits more than one oxidation state, the halides in higher oxidation state will be more covalent than the one in lower oxidation state. For example, SnCl 4 , PbCl 4 , SbCl 5 and UF 6 are more covalent than SnCl 2 , PbCl 2 , SbCl 3 and UF 4 respectively.','[{"s": "The ionic character of the halides decreases in the order MF > MCl > MBr > MI where M is a monovalent metal. If a metal exhibits more than one oxidation state, the halides in higher oxidation state will be more covalent than the one in lower oxidation state. For example, SnCl", "t": "text"}, {"s": "4", "t": "text"}, {"s": ", PbCl", "t": "text"}, {"s": "4", "t": "text"}, {"s": ", SbCl", "t": "text"}, {"s": "5", "t": "text"}, {"s": "and UF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "are more covalent than SnCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", PbCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", SbCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": "and UF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "respectively.", "t": "text"}]',NULL,NULL,NULL),
(17885,50,240,'paragraph',NULL,'Reactions (8.41) and (8.42) form the basis of identifying Br– and I– in the laboratory through the test popularly known as ‘Layer Test’. It may not be out of place to mention here that bromine likewise can displace iodide ion in solution:','[{"s": "Reactions (8.41) and (8.42) form the basis of identifying Br– and I– in the laboratory through the test popularly known as ‘Layer Test’. It may not be out of place to mention here that bromine likewise can displace iodide ion in solution:", "t": "text"}]',NULL,NULL,NULL),
(17442,49,535,'paragraph',NULL,'(iv) Reactivity of halogens towards other halogens: Halogens combine amongst themselves to form a number of compounds known as interhalogens of the types XX′, XX 3 ′, XX 5 ′ and XX 7 ′ where X is a larger size halogen and X′ is smaller size halogen.','[{"s": "(iv) Reactivity of halogens towards other halogens: Halogens combine amongst themselves to form a number of compounds known as interhalogens of the types XX′, XX", "t": "text"}, {"s": "3", "t": "text"}, {"s": "′, XX", "t": "text"}, {"s": "5", "t": "text"}, {"s": "′ and XX", "t": "text"}, {"s": "7", "t": "text"}, {"s": "′ where X is a larger size halogen and X′", "t": "text"}, {"s": "is smaller size halogen.", "t": "text"}]',NULL,NULL,NULL),
(17443,49,536,'paragraph',NULL,'Example 7.16','[{"s": "Example 7.16", "t": "text"}]',NULL,NULL,NULL),
(17444,49,537,'paragraph',NULL,'Fluorine exhibits only –1 oxidation state whereas other halogens exhibit + 1, + 3, + 5 and + 7 oxidation states also. Explain.','[{"s": "Fluorine exhibits only –1 oxidation state whereas other halogens exhibit + 1, + 3, + 5 and + 7 oxidation states also. Explain.", "t": "hl"}]','marked','["214302"]',NULL),
(17445,49,538,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17446,49,539,'paragraph',NULL,'Fluorine is the most electronegative element and cannot exhibit any positive oxidation state. Other halogens have d orbitals and therefore, can expand their octets and show + 1, + 3, + 5 and + 7 oxidation states also.','[{"s": "Fluorine is the most electronegative element and cannot exhibit any positive oxidation state. Other halogens have d orbitals and therefore, can expand their octets and show + 1, + 3, + 5 and + 7 oxidation states also.", "t": "text"}]',NULL,NULL,NULL),
(17447,49,540,'paragraph',NULL,'Intext Questions','[{"s": "Intext Questions", "t": "text"}]',NULL,NULL,NULL),
(17448,49,541,'paragraph',NULL,'7.26 Considering the parameters such as bond dissociation enthalpy, electron gain enthalpy and hydration enthalpy, compare the oxidising power of F 2 and Cl 2 .','[{"s": "7.26", "t": "text"}, {"s": "Considering the parameters such as bond dissociation enthalpy, electron gain enthalpy and hydration enthalpy, compare the oxidising power of F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "and Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17449,49,542,'paragraph',NULL,'7.27 Give two examples to show the anomalous behaviour of fluorine.','[{"s": "7.27", "t": "text"}, {"s": "Give two examples to show the anomalous behaviour of fluorine.", "t": "text"}]',NULL,NULL,NULL),
(17450,49,543,'paragraph',NULL,'7.28 Sea is the greatest source of some halogens. Comment.','[{"s": "7.28", "t": "text"}, {"s": "Sea is the greatest source of some halogens. Comment.", "t": "text"}]',NULL,NULL,NULL),
(17451,49,544,'heading',3,'7.19 CHLORINE',NULL,NULL,NULL,NULL),
(17452,49,545,'paragraph',NULL,'Chlorine was discovered in 1774 by Scheele by the action of HCl on MnO 2 . In 1810 Davy established its elementary nature and suggested the name chlorine on account of its colour (Greek, chloros = greenish yellow).','[{"s": "Chlorine was discovered in 1774 by Scheele by the action of HCl on MnO", "t": "text"}, {"s": "2", "t": "text"}, {"s": ". In 1810 Davy established its elementary nature and suggested the name chlorine on account of its colour (Greek, chloros = greenish yellow).", "t": "text"}]',NULL,NULL,NULL),
(17453,49,546,'paragraph',NULL,'Preparation','[{"s": "Preparation", "t": "text"}]',NULL,NULL,NULL),
(17454,49,547,'paragraph',NULL,'It can be prepared by any one of the following methods:','[{"s": "It can be prepared by any one of the following methods:", "t": "text"}]',NULL,NULL,NULL),
(17455,49,548,'paragraph',NULL,'(i) By heating manganese dioxide with concentrated hydrochloric acid.','[{"s": "(i) By heating manganese dioxide with concentrated hydrochloric acid.", "t": "text"}]',NULL,NULL,NULL),
(17456,49,549,'paragraph',NULL,'MnO 2 + 4HCl → MnCl 2 + Cl 2 + 2H 2 O','[{"s": "MnO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 4HCl → MnCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17457,49,550,'paragraph',NULL,'However, a mixture of common salt and concentrated H 2 SO 4 is used in place of HCl.','[{"s": "However, a mixture of common salt and concentrated H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "is used in place of HCl.", "t": "text"}]',NULL,NULL,NULL),
(17458,49,551,'paragraph',NULL,'4NaCl + MnO 2 + 4H 2 SO 4 → MnCl 2 + 4NaHSO 4 + 2H 2 O + Cl 2','[{"s": "4NaCl + MnO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 4H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "→ MnCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 4NaHSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + Cl", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17459,49,552,'paragraph',NULL,'(ii) By the action of HCl on potassium permanganate.','[{"s": "(ii) By the action of HCl on potassium permanganate.", "t": "text"}]',NULL,NULL,NULL),
(17460,49,553,'paragraph',NULL,'2KMnO 4 + 16HCl → 2KCl + 2MnCl 2 + 8H 2 O + 5Cl 2','[{"s": "2KMnO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 16HCl → 2KCl + 2MnCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 8H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + 5Cl", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17461,49,554,'paragraph',NULL,'Manufacture of chlorine','[{"s": "Manufacture of chlorine", "t": "text"}]',NULL,NULL,NULL),
(17462,49,555,'paragraph',NULL,'(i) Deacon’s process: By oxidation of hydrogen chloride gas by atmospheric oxygen in the presence of CuCl 2 (catalyst) at 723 K.','[{"s": "(i) Deacon’s process: By oxidation of hydrogen chloride gas by atmospheric oxygen in the presence of CuCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(catalyst) at 723 K.", "t": "text"}]',NULL,NULL,NULL),
(17463,49,556,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image86.png'),
(17464,49,557,'paragraph',NULL,'(ii) Electrolytic process: Chlorine is obtained by the electrolysis of brine (concentrated NaCl solution). Chlorine is liberated at anode. It is also obtained as a by–product in many chemical industries.','[{"s": "(ii) Electrolytic process: Chlorine is obtained by the electrolysis of brine (concentrated NaCl solution). Chlorine is liberated at anode. It is also obtained as a by–product in many chemical industries.", "t": "text"}]',NULL,NULL,NULL),
(17465,49,558,'paragraph',NULL,'Properties','[{"s": "Properties", "t": "text"}]',NULL,NULL,NULL),
(17886,50,241,'paragraph',NULL,'0 –1 –1 0','[{"s": "0 –1 –1 0", "t": "text"}]',NULL,NULL,NULL),
(17466,49,559,'paragraph',NULL,'It is a greenish yellow gas with pungent and suffocating odour. It is about 2-5 times heavier than air. It can be liquefied easily into greenish yellow liquid which boils at 239 K. It is soluble in water.','[{"s": "It is a greenish yellow gas with pungent and suffocating odour. It is about 2-5 times heavier than air. It can be liquefied easily into greenish yellow liquid which boils at 239 K. It is soluble in water.", "t": "text"}]',NULL,NULL,NULL),
(17467,49,560,'paragraph',NULL,'Chlorine reacts with a number of metals and non-metals to form chlorides.','[{"s": "Chlorine reacts with a number of metals and non-metals to form chlorides.", "t": "text"}]',NULL,NULL,NULL),
(17468,49,561,'paragraph',NULL,'2Al + 3Cl 2 → 2AlCl 3 ; P 4 + 6Cl 2 → 4PCl 3','[{"s": "2Al + 3Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 2AlCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": ";", "t": "text"}, {"s": "P", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 6Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 4PCl", "t": "text"}, {"s": "3", "t": "text"}]',NULL,NULL,NULL),
(17469,49,562,'paragraph',NULL,'2Na + Cl 2 → 2NaCl; S 8 + 4Cl 2 → 4S 2 Cl 2','[{"s": "2Na + Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 2NaCl; S", "t": "text"}, {"s": "8", "t": "text"}, {"s": "+ 4Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 4S", "t": "text"}, {"s": "2", "t": "text"}, {"s": "Cl", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17470,49,563,'paragraph',NULL,'2Fe + 3Cl 2 → 2FeCl 3 ;','[{"s": "2Fe + 3Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 2FeCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": ";", "t": "text"}]',NULL,NULL,NULL),
(17471,49,564,'paragraph',NULL,'It has great affinity for hydrogen. It reacts with compounds containing hydrogen to form HCl.','[{"s": "It has great affinity for hydrogen. It reacts with compounds containing hydrogen to form HCl.", "t": "text"}]',NULL,NULL,NULL),
(17472,49,565,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image78.png'),
(17473,49,566,'paragraph',NULL,'With cold and dilute alkalies chlorine produces a mixture of chloride and hypochlorite but with hot and concentrated alkalies it gives chloride and chlorate.','[{"s": "With cold and dilute alkalies chlorine produces a mixture of chloride and hypochlorite but with hot and concentrated alkalies it gives chloride and chlorate.", "t": "text"}]',NULL,NULL,NULL),
(17474,49,567,'paragraph',NULL,'2NaOH + Cl 2 → NaCl + NaOCl + H 2 O','[{"s": "2NaOH + Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ NaCl + NaOCl + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17475,49,568,'paragraph',NULL,'(cold and dilute)','[{"s": "(cold and dilute)", "t": "text"}]',NULL,NULL,NULL),
(17476,49,569,'paragraph',NULL,'6 NaOH + 3Cl 2 → 5NaCl + NaClO 3 + 3H 2 O','[{"s": "6 NaOH + 3Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 5NaCl + NaClO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 3H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17477,49,570,'paragraph',NULL,'(hot and conc.)','[{"s": "(hot and conc.)", "t": "text"}]',NULL,NULL,NULL),
(17478,49,571,'paragraph',NULL,'With dry slaked lime it gives bleaching powder.','[{"s": "With dry slaked lime it gives bleaching powder.", "t": "text"}]',NULL,NULL,NULL),
(17479,49,572,'paragraph',NULL,'2Ca(OH) 2 + 2Cl 2 → Ca(OCl) 2 + CaCl 2 + 2H 2 O','[{"s": "2Ca(OH)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ Ca(OCl)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ CaCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17480,49,573,'paragraph',NULL,'The composition of bleaching powder is Ca(OCl) 2 .CaCl 2 .Ca(OH) 2 .2H 2 O.','[{"s": "The composition of bleaching powder is Ca(OCl)", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".CaCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".Ca(OH)", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O.", "t": "text"}]',NULL,NULL,NULL),
(17481,49,574,'paragraph',NULL,'Chlorine reacts with hydrocarbons and gives substitution products with saturated hydrocarbons and addition products with unsaturated hydrocarbons. For example,','[{"s": "Chlorine reacts with hydrocarbons and gives substitution products with saturated hydrocarbons and addition products with unsaturated hydrocarbons. For example,", "t": "text"}]',NULL,NULL,NULL),
(17482,49,575,'paragraph',NULL,'CH 4 + Cl 2 P_Block_Elements_Group_15_to_18-image98.png CH 3 Cl + HCl','[{"s": "CH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image98.png", "t": "img", "alt": ""}, {"s": "CH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "Cl + HCl", "t": "text"}]',NULL,NULL,NULL),
(17483,49,576,'paragraph',NULL,'Methane Methyl chloride','[{"s": "Methane Methyl chloride", "t": "text"}]',NULL,NULL,NULL),
(17484,49,577,'paragraph',NULL,'C 2 H 4 + Cl 2 P_Block_Elements_Group_15_to_18-image56.png C 2 H 4 Cl 2','[{"s": "C", "t": "text"}, {"s": "2", "t": "text"}, {"s": "H", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image56.png", "t": "img", "alt": ""}, {"s": "C", "t": "text"}, {"s": "2", "t": "text"}, {"s": "H", "t": "text"}, {"s": "4", "t": "text"}, {"s": "Cl", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17485,49,578,'paragraph',NULL,'Ethene 1,2-Dichloroethane','[{"s": "Ethene 1,2-Dichloroethane", "t": "text"}]',NULL,NULL,NULL),
(17486,49,579,'paragraph',NULL,'Chlorine water on standing loses its yellow colour due to the formation of HCl and HOCl. Hypochlorous acid (HOCl) so formed, gives nascent oxygen which is responsible for oxidising and bleaching properties of chlorine.','[{"s": "Chlorine water on standing loses its yellow colour due to the formation of HCl and HOCl. Hypochlorous acid (HOCl) so formed, gives nascent oxygen which is responsible for oxidising and bleaching properties of chlorine.", "t": "text"}]',NULL,NULL,NULL),
(17487,49,580,'paragraph',NULL,'Chlorine oxidises ferrous to ferric and sulphite to sulphate. Chlorine oxidises sulphur dioxide to sulphur trioxide and iodine to iodate. In the presence of water they form sulphuric acid and iodic acid respectively.','[{"s": "Chlorine oxidises ferrous to ferric and sulphite to sulphate. Chlorine oxidises sulphur dioxide to sulphur trioxide and iodine to iodate. In the presence of water they form sulphuric acid and iodic acid respectively.", "t": "text"}]',NULL,NULL,NULL),
(17488,49,581,'paragraph',NULL,'2FeSO 4 + H 2 SO 4 + Cl 2 → Fe 2 (SO 4 ) 3 + 2HCl','[{"s": "2FeSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ Fe", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": ")", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 2HCl", "t": "text"}]',NULL,NULL,NULL),
(17489,49,582,'paragraph',NULL,'Na 2 SO 3 + Cl 2 + H 2 O → Na 2 SO 4 + 2HCl','[{"s": "Na", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O → Na", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 2HCl", "t": "text"}]',NULL,NULL,NULL),
(17490,49,583,'paragraph',NULL,'SO 2 + 2H 2 O + Cl 2 → H 2 SO 4 + 2HCl','[{"s": "SO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 2HCl", "t": "text"}]',NULL,NULL,NULL),
(17491,49,584,'paragraph',NULL,'I 2 + 6H 2 O + 5Cl 2 → 2HIO 3 + 10HCl','[{"s": "I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 6H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + 5Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "→ 2HIO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 10HCl", "t": "text"}]',NULL,NULL,NULL),
(17492,49,585,'paragraph',NULL,'Chlorine is a powerful bleaching agent; bleaching action is due to oxidation.','[{"s": "Chlorine is a powerful bleaching agent; bleaching action is due to oxidation.", "t": "hl"}]','marked','["214273", "214274"]',NULL),
(17493,49,586,'paragraph',NULL,'It bleaches vegetable or organic matter in the presence of moisture. Bleaching effect of chlorine is permanent.','[{"s": "It bleaches vegetable or organic matter in the presence of moisture. Bleaching effect of chlorine is permanent.", "t": "text"}]',NULL,NULL,NULL),
(17494,49,587,'paragraph',NULL,'Cl 2 + H 2 O → 2HCl + O','[{"s": "Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O → 2HCl + O", "t": "text"}]',NULL,NULL,NULL),
(17495,49,588,'paragraph',NULL,'Coloured substance + O → Colourless substance','[{"s": "Coloured substance + O → Colourless substance", "t": "text"}]',NULL,NULL,NULL),
(17496,49,589,'paragraph',NULL,'Uses : It is used (i) for bleaching woodpulp (required for the manufacture of paper and rayon), bleaching cotton and textiles, (ii) in the extraction of gold and platinum (iii) in the manufacture of dyes, drugs and organic compounds such as CCl 4 , CHCl 3 , DDT, refrigerants, etc. (iv) in sterilising drinking water and (v) preparation of poisonous gases such as phosgene (COCl 2 ), tear gas (CCl 3 NO 2 ), mustard gas (ClCH 2 CH 2 SCH 2 CH 2 Cl).','[{"s": "Uses", "t": "text"}, {"s": ": It is used (i) for bleaching woodpulp (required for the manufacture of paper and rayon), bleaching cotton and textiles, (ii) in the extraction of gold and platinum (iii) in the manufacture of dyes, drugs and organic compounds such as CCl", "t": "text"}, {"s": "4", "t": "text"}, {"s": ", CHCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": ", DDT, refrigerants, etc. (iv) in sterilising drinking water and (v) preparation of poisonous gases such as phosgene (COCl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "), tear gas (CCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": "NO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "), mustard gas (ClCH", "t": "text"}, {"s": "2", "t": "text"}, {"s": "CH", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SCH", "t": "text"}, {"s": "2", "t": "text"}, {"s": "CH", "t": "text"}, {"s": "2", "t": "text"}, {"s": "Cl).", "t": "text"}]',NULL,NULL,NULL),
(17497,49,590,'paragraph',NULL,'Example 7.17','[{"s": "Example 7.17", "t": "text"}]',NULL,NULL,NULL),
(17498,49,591,'paragraph',NULL,'Write the balanced chemical equation for the reaction of Cl 2 with hot and concentrated NaOH. Is this reaction a disproportionation reaction? Justify.','[{"s": "Write the balanced chemical equation for the reaction of Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "with hot and concentrated NaOH. Is this reaction a disproportionation reaction? Justify.", "t": "text"}]',NULL,NULL,NULL),
(17499,49,592,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17500,49,593,'paragraph',NULL,'3Cl 2 + 6NaOH → 5NaCl + NaClO 3 + 3H 2 O','[{"s": "3Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 6NaOH → 5NaCl + NaClO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 3H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(17501,49,594,'paragraph',NULL,'Yes, chlorine from zero oxidation state is changed to –1 and +5 oxidation states.','[{"s": "Yes, chlorine from zero oxidation state is changed to –1 and +5 oxidation states.", "t": "text"}]',NULL,NULL,NULL),
(17502,49,595,'paragraph',NULL,'Intext Questions','[{"s": "Intext Questions", "t": "text"}]',NULL,NULL,NULL),
(17503,49,596,'paragraph',NULL,'7.29 Give the reason for bleaching action of Cl 2 .','[{"s": "7.29", "t": "text"}, {"s": "Give the reason for bleaching action of Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17504,49,597,'paragraph',NULL,'7.30 Name two poisonous gases which can be prepared from chlorine gas.','[{"s": "7.30", "t": "text"}, {"s": "Name two poisonous gases which can be prepared from chlorine gas.", "t": "text"}]',NULL,NULL,NULL),
(17505,49,598,'heading',3,'7.20 HYDROGEN CHLORIDE',NULL,NULL,NULL,NULL),
(17506,49,599,'paragraph',NULL,'Glauber prepared this acid in 1648 by heating common salt with concentrated sulphuric acid. Davy in 1810 showed that it is a compound of hydrogen and chlorine.','[{"s": "Glauber prepared this acid in 1648 by heating common salt with concentrated sulphuric acid. Davy in 1810 showed that it is a compound of hydrogen and chlorine.", "t": "text"}]',NULL,NULL,NULL),
(17507,49,600,'paragraph',NULL,'Preparation','[{"s": "Preparation", "t": "text"}]',NULL,NULL,NULL),
(17508,49,601,'paragraph',NULL,'In laboratory, it is prepared by heating sodium chloride with concentrated sulphuric acid.','[{"s": "In laboratory, it is prepared by heating sodium chloride with concentrated sulphuric acid.", "t": "text"}]',NULL,NULL,NULL),
(17509,49,602,'paragraph',NULL,'NaCl + H 2 SO 4 P_Block_Elements_Group_15_to_18-image3.png NaHSO 4 + HCl','[{"s": "NaCl + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image3.png", "t": "img", "alt": ""}, {"s": "NaHSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ HCl", "t": "text"}]',NULL,NULL,NULL),
(17510,49,603,'paragraph',NULL,'NaHSO 4 + NaCl P_Block_Elements_Group_15_to_18-image91.png Na 2 SO 4 + HCl','[{"s": "NaHSO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ NaCl", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image91.png", "t": "img", "alt": ""}, {"s": "Na", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ HCl", "t": "text"}]',NULL,NULL,NULL),
(17511,49,604,'paragraph',NULL,'HCl gas can be dried by passing through concentrated sulphuric acid.','[{"s": "HCl gas can be dried by passing through concentrated sulphuric acid.", "t": "text"}]',NULL,NULL,NULL),
(17512,49,605,'paragraph',NULL,'Properties','[{"s": "Properties", "t": "text"}]',NULL,NULL,NULL),
(17513,49,606,'paragraph',NULL,'It is a colourless and pungent smelling gas. It is easily liquefied to a colourless liquid (b.p.189 K) and freezes to a white crystalline solid (f.p. 159 K). It is extremely soluble in water and ionises as follows:','[{"s": "It is a colourless and pungent smelling gas. It is easily liquefied to a colourless liquid (b.p.189 K) and freezes to a white crystalline solid (f.p. 159 K). It is extremely soluble in water and ionises as follows:", "t": "text"}]',NULL,NULL,NULL),
(17514,49,607,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image20.png'),
(17515,49,608,'paragraph',NULL,'Its aqueous solution is called hydrochloric acid. High value of dissociation constant (K a ) indicates that it is a strong acid in water. It reacts with NH 3 and gives white fumes of NH 4 Cl.','[{"s": "Its aqueous solution is called hydrochloric acid. High value of dissociation constant (K", "t": "text"}, {"s": "a", "t": "text"}, {"s": ") indicates that it is a strong acid in water. It reacts with NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "and gives white fumes of NH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "Cl.", "t": "text"}]',NULL,NULL,NULL),
(17516,49,609,'paragraph',NULL,'NH 3 + HCl → NH 4 Cl','[{"s": "NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ HCl → NH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "Cl", "t": "text"}]',NULL,NULL,NULL),
(17517,49,610,'paragraph',NULL,'When three parts of concentrated HCl and one part of concentrated HNO 3 are mixed, aqua regia is formed which is used for dissolving noble metals, e.g., gold, platinum.','[{"s": "When three parts of concentrated HCl and one part of concentrated HNO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "are mixed,", "t": "text"}, {"s": "aqua regia", "t": "text"}, {"s": "is formed which is used for dissolving noble metals, e.g., gold, platinum.", "t": "text"}]',NULL,NULL,NULL),
(17518,49,611,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image101.png'),
(17519,49,612,'paragraph',NULL,'Hydrochloric acid decomposes salts of weaker acids, e.g., carbonates, hydrogencarbonates, sulphites, etc.','[{"s": "Hydrochloric acid decomposes salts of weaker acids, e.g., carbonates, hydrogencarbonates, sulphites, etc.", "t": "text"}]',NULL,NULL,NULL),
(17520,49,613,'paragraph',NULL,'Na 2 CO 3 + 2HCl → 2NaCl + H 2 O + CO 2','[{"s": "Na", "t": "text"}, {"s": "2", "t": "text"}, {"s": "CO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 2HCl → 2NaCl + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + CO", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17521,49,614,'paragraph',NULL,'NaHCO 3 + HCl → NaCl + H 2 O + CO 2','[{"s": "NaHCO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ HCl → NaCl + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + CO", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17522,49,615,'paragraph',NULL,'Na 2 SO 3 + 2HCl → 2NaCl + H 2 O + SO 2','[{"s": "Na", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 2HCl → 2NaCl + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + SO", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17523,49,616,'paragraph',NULL,'Uses : It is used (i) in the manufacture of chlorine, NH 4 Cl and glucose (from corn starch), (ii) for extracting glue from bones and purifying bone black, (iii) in medicine and as a laboratory reagent.','[{"s": "Uses", "t": "text"}, {"s": ": It is used (i) in the manufacture of chlorine, NH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "Cl and glucose (from corn starch), (ii) for extracting glue from bones and purifying bone black, (iii) in medicine and as a laboratory reagent.", "t": "text"}]',NULL,NULL,NULL),
(17524,49,617,'paragraph',NULL,'Example 7.18','[{"s": "Example 7.18", "t": "text"}]',NULL,NULL,NULL),
(17525,49,618,'paragraph',NULL,'When HCl reacts with finely powdered iron, it forms ferrous chloride and not ferric chloride. Why?','[{"s": "When HCl reacts with finely powdered iron, it forms ferrous chloride and not ferric chloride. Why?", "t": "text"}]',NULL,NULL,NULL),
(17526,49,619,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17527,49,620,'paragraph',NULL,'Its reaction with iron produces H 2 .','[{"s": "Its reaction with iron produces H", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17528,49,621,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image43.png'),
(17529,49,622,'paragraph',NULL,'Liberation of hydrogen prevents the formation of ferric chloride.','[{"s": "Liberation of hydrogen prevents the formation of ferric chloride.", "t": "text"}]',NULL,NULL,NULL),
(17530,49,623,'heading',3,'7.21 OXOACIDS OF HALOGENS',NULL,NULL,NULL,NULL),
(17531,49,624,'paragraph',NULL,'Due to high electronegativity and small size, fluorine forms only one oxoacid, HOF known as fluoric (I) acid or hypofluorous acid. The other halogens form several oxoacids. Most of them cannot be isolated in pure state. They are stable only in aqueous solutions or in the form of their salts. The oxoacids of halogens are given in Table 7.10 and their structures are given in Fig. 7.8.','[{"s": "Due to high electronegativity and small size, fluorine forms only one oxoacid, HOF known as fluoric (I) acid or hypofluorous acid. The other halogens form several oxoacids. Most of them cannot be isolated in pure state. They are stable only in aqueous solutions or in the form of their salts. The oxoacids of halogens are given in Table 7.10 and their structures are given in Fig. 7.8.", "t": "text"}]',NULL,NULL,NULL),
(17532,49,625,'paragraph',NULL,'Table 7.10: Oxoacids of Halogens','[{"s": "Table 7.10: Oxoacids of Halogens", "t": "text"}]',NULL,NULL,NULL),
(17533,49,626,'image',NULL,'7k',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image33.png'),
(17534,49,627,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image84.png');
INSERT INTO `ncert_book_blocks` (`id`, `chapter_id`, `idx`, `type`, `level`, `text`, `content`, `status`, `pyq_ids`, `image_url`) VALUES
(17535,49,628,'paragraph',NULL,'Fig. 7.8 The structures of oxoacids of chlorine','[{"s": "Fig. 7.8", "t": "text"}, {"s": "The structures of oxoacids of chlorine", "t": "text"}]',NULL,NULL,NULL),
(17536,49,629,'heading',3,'7.22 INTERHALOGEN COMPOUNDS',NULL,NULL,NULL,NULL),
(17537,49,630,'paragraph',NULL,'When two different halogens react with each other, interhalogen compounds are formed. They can be assigned general compositions as XX′ , XX 3 ′, XX 5 ′ and XX 7 ′ where X is halogen of larger size and X′ of smaller size and X is more electropositive than X′. As the ratio between radii of X and X′ increases, the number of atoms per molecule also increases. Thus, iodine (VII) fluoride should have maximum number of atoms as the ratio of radii between I and F should be maximum. That is why its formula is IF 7 (having maximum number of atoms).','[{"s": "When two different halogens react with each other, interhalogen compounds are formed. They can be assigned general compositions as XX′ , XX", "t": "text"}, {"s": "3", "t": "text"}, {"s": "′, XX", "t": "text"}, {"s": "5", "t": "text"}, {"s": "′ and XX", "t": "text"}, {"s": "7", "t": "text"}, {"s": "′ where X is halogen of larger size and X′", "t": "text"}, {"s": "of smaller size and X is more electropositive than X′.", "t": "text"}, {"s": "As the ratio between radii of X and X′ increases, the number of atoms per molecule also increases.", "t": "hl"}, {"s": "Thus, iodine (VII) fluoride should have maximum number of atoms as the ratio of radii between I and F should be maximum. That is why its formula is IF", "t": "text"}, {"s": "7", "t": "text"}, {"s": "(having maximum number of atoms).", "t": "text"}]','marked','["214285"]',NULL),
(17538,49,631,'paragraph',NULL,'Preparation','[{"s": "Preparation", "t": "text"}]',NULL,NULL,NULL),
(17539,49,632,'paragraph',NULL,'The interhalogen compounds can be prepared by the direct combination or by the action of halogen on lower interhalogen compounds. The product formed depends upon some specific conditions, For example,','[{"s": "The interhalogen compounds can be prepared by the direct combination or by the action of halogen on lower interhalogen compounds. The product formed depends upon some specific conditions, For example,", "t": "text"}]',NULL,NULL,NULL),
(17540,49,633,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image90.png'),
(17541,49,634,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image18.png'),
(17542,49,635,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image16.png'),
(17543,49,636,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image68.png'),
(17544,49,637,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image110.png'),
(17545,49,638,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image61.png'),
(17546,49,639,'paragraph',NULL,'Properties','[{"s": "Properties", "t": "text"}]',NULL,NULL,NULL),
(17547,49,640,'paragraph',NULL,'Some properties of interhalogen compounds are given in Table 7.11.','[{"s": "Some properties of interhalogen compounds are given in Table 7.11.", "t": "text"}]',NULL,NULL,NULL),
(17548,49,641,'paragraph',NULL,'Table 7.11: Some Properties of Interhalogen Compounds 2','[{"s": "Table 7.11: Some Properties of Interhalogen Compounds", "t": "hl"}, {"s": "2", "t": "text"}]','marked','["214278", "214305"]',NULL),
(17549,49,642,'image',NULL,'7l',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image76.png'),
(17550,49,643,'paragraph',NULL,'These are all covalent molecules and are diamagnetic in nature. They are volatile solids or liquids at 298 K except ClF which is a gas. Their physical properties are intermediate between those of constituent halogens except that their m.p. and b.p. are a little higher than expected.','[{"s": "These are all covalent molecules and are diamagnetic in nature. They are volatile solids or liquids at 298 K except ClF which is a gas. Their physical properties are intermediate between those of constituent halogens except that their m.p. and b.p. are a little higher than expected.", "t": "text"}]',NULL,NULL,NULL),
(17551,49,644,'paragraph',NULL,'Their chemical reactions can be compared with the individual halogens. In general, interhalogen compounds are more reactive than halogens (except fluorine). This is because X–X′ bond in interhalogens is weaker than X–X bond in halogens except F–F bond. All these undergo hydrolysis giving halide ion derived from the smaller halogen and a hypohalite ( when XX′), halite ( when XX′ 3 ), halate (when XX′ 5 ) and perhalate (when XX′ 7 ) anion derived from the larger halogen.','[{"s": "Their chemical reactions can be compared with the individual halogens. In general, interhalogen compounds are more reactive than halogens (except fluorine). This is because X–X′ bond in interhalogens is weaker than X–X bond in halogens except F–F bond.", "t": "text"}, {"s": "All these undergo hydrolysis giving halide ion derived from the smaller halogen and a hypohalite ( when XX′), halite ( when XX′", "t": "hl"}, {"s": "3", "t": "hl"}, {"s": "), halate (when XX′", "t": "hl"}, {"s": "5", "t": "hl"}, {"s": ") and perhalate (when XX′", "t": "hl"}, {"s": "7", "t": "hl"}, {"s": ") anion derived from the larger halogen.", "t": "hl"}]','marked','["214306"]',NULL),
(17552,49,645,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image42.png'),
(17553,49,646,'paragraph',NULL,'Their molecular structures are very interesting which can be explained on the basis of VSEPR theory (Example 7.19). The XX 3 compounds have the bent ‘T’ shape, XX 5 compounds square pyramidal and IF 7 has pentagonal bipyramidal structures (Table 7.11).','[{"s": "Their molecular structures are very interesting which can be explained on the basis of VSEPR theory (Example 7.19).", "t": "hl"}, {"s": "The XX", "t": "text"}, {"s": "3", "t": "text"}, {"s": "compounds have the bent ‘T’ shape, XX", "t": "text"}, {"s": "5", "t": "text"}, {"s": "compounds square pyramidal and IF", "t": "text"}, {"s": "7", "t": "text"}, {"s": "has pentagonal bipyramidal structures (Table 7.11).", "t": "text"}]','marked','["214278"]',NULL),
(17554,49,647,'paragraph',NULL,'Example 7.19','[{"s": "Example 7.19", "t": "text"}]',NULL,NULL,NULL),
(17555,49,648,'paragraph',NULL,'Discuss the molecular shape of BrF 3 on the basis of VSEPR theory.','[{"s": "Discuss the molecular shape of BrF", "t": "text"}, {"s": "3", "t": "text"}, {"s": "on the basis of VSEPR theory.", "t": "text"}]',NULL,NULL,NULL),
(17556,49,649,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17557,49,650,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image93.png'),
(17558,49,651,'paragraph',NULL,'The central atom Br has seven electrons in the valence shell. Three of these will form electron-pair bonds with three fluorine atoms leaving behind four electrons. Thus, there are three bond pairs and two lone pairs. According to VSEPR theory, these will occupy the corners of a trigonal bipyramid. The two lone pairs will occupy the equatorial positions to minimise lone pair-lone pair and the bond pair-lone pair repulsions which are greater than the bond pair-bond pair repulsions. In addition, the axial fluorine atoms will be bent towards the equatorial fluorine in order to minimise the lone-pair-lone pair repulsions. The shape would be that of a slightly bent ‘T’.','[{"s": "The central atom Br has seven electrons in the valence shell. Three of these will form electron-pair bonds with three fluorine atoms leaving behind four electrons. Thus, there are three bond pairs and two lone pairs. According to VSEPR theory, these will occupy the corners of a trigonal bipyramid. The two lone pairs will occupy the equatorial positions to minimise lone pair-lone pair and the bond pair-lone pair repulsions which are greater than the bond pair-bond pair repulsions. In addition, the axial fluorine atoms will be bent towards the equatorial fluorine in order to minimise the lone-pair-lone pair repulsions. The shape would be that of a slightly bent ‘T’.", "t": "text"}]',NULL,NULL,NULL),
(17559,49,652,'paragraph',NULL,'Uses : These compounds can be used as non aqueous solvents. Interhalogen compounds are very useful fluorinating agents. ClF 3 and BrF 3 are used for the production of UF 6 in the enrichment of 235 U.','[{"s": "Uses", "t": "text"}, {"s": ": These compounds can be used as non aqueous solvents. Interhalogen compounds are very useful fluorinating agents. ClF", "t": "text"}, {"s": "3", "t": "text"}, {"s": "and BrF", "t": "text"}, {"s": "3", "t": "text"}, {"s": "are used for the production of UF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "in the enrichment of", "t": "text"}, {"s": "235", "t": "text"}, {"s": "U.", "t": "text"}]',NULL,NULL,NULL),
(17560,49,653,'paragraph',NULL,'U(s) + 3ClF 3 (l) → UF 6 (g) + 3ClF(g)','[{"s": "U(s) + 3ClF", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(l) → UF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "(g) + 3ClF(g)", "t": "text"}]',NULL,NULL,NULL),
(17561,49,654,'heading',3,'7.23 GROUP 18 ELEMENTS',NULL,NULL,NULL,NULL),
(17562,49,655,'paragraph',NULL,'Group 18 consists of elements: helium, neon, argon, krypton, xenon, radon and oganesson. All these are gases and chemically unreactive. They form very few compounds, because of this they are termed as noble gases .','[{"s": "Group 18 consists of elements: helium, neon, argon, krypton, xenon, radon and oganesson. All these are gases and chemically unreactive. They form very few compounds, because of this they are termed as", "t": "text"}, {"s": "noble gases", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17563,49,656,'paragraph',NULL,'7.23.1 Occurrence','[{"s": "7.23.1 Occurrence", "t": "text"}]',NULL,NULL,NULL),
(17564,49,657,'paragraph',NULL,'All these gases except radon and oganesson occur in the atmosphere. Their atmospheric abundance in dry air is ~ 1% by volume of which argon is the major constituent. Helium and sometimes neon are found in minerals of radioactive origin e.g., pitchblende, monazite, cleveite. The main commercial source of helium is natural gas. Xenon and radon are the rarest elements of the group. Radon is obtained as a decay product of 226 Ra.','[{"s": "All these gases except radon and oganesson occur in the atmosphere. Their atmospheric abundance in dry air is ~ 1% by volume of which argon is the major constituent. Helium and sometimes neon are found in minerals of radioactive origin e.g., pitchblende, monazite, cleveite. The main commercial source of helium is natural gas. Xenon and radon are the rarest elements of the group. Radon is obtained as a decay product of", "t": "text"}, {"s": "226", "t": "text"}, {"s": "Ra.", "t": "text"}]',NULL,NULL,NULL),
(17565,49,658,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image48.png'),
(17566,49,659,'paragraph',NULL,'Oganesson has been synthetically produced by collision of P_Block_Elements_Group_15_to_18-image45.png atoms and P_Block_Elements_Group_15_to_18-image35.png ions','[{"s": "Oganesson has been synthetically produced by collision of", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image45.png", "t": "img", "alt": ""}, {"s": "atoms and", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image35.png", "t": "img", "alt": ""}, {"s": "ions", "t": "text"}]',NULL,NULL,NULL),
(17567,49,660,'image',NULL,'7eq7',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image51.png'),
(17568,49,661,'paragraph',NULL,'Example 7.20','[{"s": "Example 7.20", "t": "text"}]',NULL,NULL,NULL),
(17569,49,662,'paragraph',NULL,'Why are the elements of Group 18 known as noble gases ?','[{"s": "Why are the elements of Group 18 known as noble gases ?", "t": "text"}]',NULL,NULL,NULL),
(17570,49,663,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17571,49,664,'paragraph',NULL,'The elements present in Group 18 have their valence shell orbitals completely filled and, therefore, react with a few elements only under certain conditions. Therefore, they are now known as noble gases.','[{"s": "The elements present in Group 18 have their valence shell orbitals completely filled and, therefore, react with a few elements only under certain conditions. Therefore, they are now known as noble gases.", "t": "text"}]',NULL,NULL,NULL),
(17572,49,665,'paragraph',NULL,'Oganesson has its symbol Og, atomic number 118, atomic mass 294 and electronic configuration [Rn] 5f 14 6d 10 7s 2 7p 6 . Only very small amount of Og has been produced. Its half life is 0.7 milliseconds. Therefore, mainly predictions about its chemistry have been made.','[{"s": "Oganesson has its symbol Og, atomic number 118, atomic mass 294 and electronic configuration [Rn] 5f", "t": "text"}, {"s": "14", "t": "text"}, {"s": "6d", "t": "text"}, {"s": "10", "t": "text"}, {"s": "7s", "t": "text"}, {"s": "2", "t": "text"}, {"s": "7p", "t": "text"}, {"s": "6", "t": "text"}, {"s": ". Only very small amount of Og has been produced. Its half life is 0.7 milliseconds. Therefore, mainly predictions about its chemistry have been made.", "t": "text"}]',NULL,NULL,NULL),
(17573,49,666,'paragraph',NULL,'Here, except for oganesson, important atomic and physical properties of other elements of Group 18 along with their electronic configurations are given in Table 7.12. The trends in some of the atomic, physical and chemical properties of the group are discussed here.','[{"s": "Here, except for oganesson, important atomic and physical properties of other elements of Group 18 along with their electronic configurations are given in Table 7.12. The trends in some of the atomic, physical and chemical properties of the group are discussed here.", "t": "text"}]',NULL,NULL,NULL),
(17574,49,667,'paragraph',NULL,'Table 7.12: Atomic and Physical Properties of Group 18 Elements','[{"s": "Table 7.12: Atomic and Physical Properties of Group 18 Elements", "t": "text"}]',NULL,NULL,NULL),
(17575,49,668,'image',NULL,'7m',NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image28.png'),
(17576,49,669,'heading',4,'7.23.2 ELECTRONIC CONFIGURATION',NULL,NULL,NULL,NULL),
(17577,49,670,'paragraph',NULL,'All noble gases have general electronic configuration ns 2 np 6 except helium which has 1s 2 (Table 7.12). Many of the properties of noble gases including their inactive nature are ascribed to their closed shell structures.','[{"s": "All noble gases have general electronic configuration ns", "t": "text"}, {"s": "2", "t": "text"}, {"s": "np", "t": "text"}, {"s": "6", "t": "text"}, {"s": "except helium which has 1s", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(Table 7.12). Many of the properties of noble gases including their inactive nature are ascribed to their closed shell structures.", "t": "text"}]',NULL,NULL,NULL),
(17578,49,671,'heading',4,'7.23.3 IONISATION ENTHALPY',NULL,NULL,NULL,NULL),
(17579,49,672,'paragraph',NULL,'Due to stable electronic configuration these gases exhibit very high ionisation enthalpy. However, it decreases down the group with increase in atomic size.','[{"s": "Due to stable electronic configuration these gases exhibit very high ionisation enthalpy. However, it decreases down the group with increase in atomic size.", "t": "text"}]',NULL,NULL,NULL),
(17580,49,673,'heading',4,'7.23.4 ATOMIC RADII',NULL,NULL,NULL,NULL),
(17581,49,674,'paragraph',NULL,'Atomic radii increase down the group with increase in atomic number.','[{"s": "Atomic radii increase down the group with increase in atomic number.", "t": "text"}]',NULL,NULL,NULL),
(17582,49,675,'heading',4,'7.23.5 ELECTRON GAIN ENTHALPY',NULL,NULL,NULL,NULL),
(17583,49,676,'paragraph',NULL,'Since noble gases have stable electronic configurations, they have no tendency to accept the electron and therefore, have large positive values of electron gain enthalpy.','[{"s": "Since noble gases have stable electronic configurations, they have no tendency to accept the electron and therefore, have large positive values of electron gain enthalpy.", "t": "text"}]',NULL,NULL,NULL),
(17584,49,677,'paragraph',NULL,'Physical Properties','[{"s": "Physical Properties", "t": "text"}]',NULL,NULL,NULL),
(17585,49,678,'paragraph',NULL,'All the noble gases are monoatomic. They are colourless, odourless and tasteless. They are sparingly soluble in water. They have very low melting and boiling points because the only type of interatomic interaction in these elements is weak dispersion forces. Helium has the lowest boiling point (4.2 K) of any known substance. It has an unusual property of diffusing through most commonly used laboratory materials such as rubber, glass or plastics.','[{"s": "All the noble gases are monoatomic. They are colourless, odourless and tasteless. They are sparingly soluble in water.", "t": "text"}, {"s": "They have very low melting and boiling points because the only type of interatomic interaction in these elements is weak dispersion forces.", "t": "hl"}, {"s": "Helium has the lowest boiling point (4.2 K) of any known substance. It has an unusual property of diffusing through most commonly used laboratory materials such as rubber, glass or plastics.", "t": "text"}]','marked','["214307"]',NULL),
(17586,49,679,'paragraph',NULL,'Example 7.21','[{"s": "Example 7.21", "t": "text"}]',NULL,NULL,NULL),
(17587,49,680,'paragraph',NULL,'Noble gases have very low boiling points. Why?','[{"s": "Noble gases have very low boiling points. Why?", "t": "text"}]',NULL,NULL,NULL),
(17588,49,681,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(17589,49,682,'paragraph',NULL,'Noble gases being monoatomic have no interatomic forces except weak dispersion forces and therefore, they are liquefied at very low temperatures. Hence, they have low boiling points.','[{"s": "Noble gases being monoatomic have no interatomic forces except weak dispersion forces and therefore, they are liquefied at very low temperatures. Hence, they have low boiling points.", "t": "text"}]',NULL,NULL,NULL),
(17590,49,683,'paragraph',NULL,'Chemical Properties','[{"s": "Chemical Properties", "t": "text"}]',NULL,NULL,NULL),
(17591,49,684,'paragraph',NULL,'In general, noble gases are least reactive. Their inertness to chemical reactivity is attributed to the following reasons:','[{"s": "In general, noble gases are least reactive. Their inertness to chemical reactivity is attributed to the following reasons:", "t": "text"}]',NULL,NULL,NULL),
(17592,49,685,'paragraph',NULL,'(i) The noble gases except helium (1s 2 ) have completely filled ns 2 np 6 electronic configuration in their valence shell.','[{"s": "(i) The noble gases except helium (1s", "t": "text"}, {"s": "2", "t": "text"}, {"s": ") have completely filled ns", "t": "text"}, {"s": "2", "t": "text"}, {"s": "np", "t": "text"}, {"s": "6", "t": "text"}, {"s": "electronic configuration in their valence shell.", "t": "text"}]',NULL,NULL,NULL),
(17593,49,686,'paragraph',NULL,'(ii) They have high ionisation enthalpy and more positive electron gain enthalpy.','[{"s": "(ii) They have high ionisation enthalpy and more positive electron gain enthalpy.", "t": "text"}]',NULL,NULL,NULL),
(17594,49,687,'paragraph',NULL,'The reactivity of noble gases has been investigated occasionally, ever since their discovery, but all attempts to force them to react to form the compounds, were unsuccessful for quite a few years. In March 1962, Neil Bartlett, then at the University of British Columbia, observed the reaction of a noble gas. First, he prepared a red compound which is formulated as O 2 + PtF 6 – . He, then realised that the first ionisation enthalpy of molecular oxygen (1175 kJmol –1 ) was almost identical with that of xenon (1170 kJ mol –1 ). He made efforts to prepare same type of compound with Xe and was successful in preparing another red colour compound Xe + PtF 6 – by mixing PtF 6 and xenon. After this discovery, a number of xenon compounds mainly with most electronegative elements like fluorine and oxygen, have been synthesised.','[{"s": "The reactivity of noble gases has been investigated occasionally, ever since their discovery, but all attempts to force them to react to form the compounds, were unsuccessful for quite a few years. In March 1962, Neil Bartlett, then at the University of British Columbia, observed the reaction of a noble gas. First, he prepared a red compound which is formulated as O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+", "t": "text"}, {"s": "PtF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "–", "t": "text"}, {"s": ". He, then realised that the first ionisation enthalpy of molecular oxygen (1175 kJmol", "t": "text"}, {"s": "–1", "t": "text"}, {"s": ") was almost identical with that of xenon (1170 kJ mol", "t": "text"}, {"s": "–1", "t": "text"}, {"s": "). He made efforts to prepare same type of compound with Xe and was successful in preparing another red colour compound Xe", "t": "text"}, {"s": "+", "t": "text"}, {"s": "PtF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "–", "t": "text"}, {"s": "by mixing PtF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "and xenon. After this discovery, a number of xenon compounds mainly with most electronegative elements like fluorine and oxygen, have been synthesised.", "t": "text"}]',NULL,NULL,NULL),
(17887,50,242,'paragraph',NULL,'Br 2 (l) + 2I – (aq) → 2Br – (aq) + I 2 (s) (8.43)','[{"s": "Br", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(l) + 2I", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq)", "t": "text"}, {"s": "→", "t": "text"}, {"s": "2Br", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq) + I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(s) (8.43)", "t": "text"}]',NULL,NULL,NULL),
(17595,49,688,'paragraph',NULL,'The compounds of krypton are fewer. Only the difluoride (KrF 2 ) has been studied in detail. Compounds of radon have not been isolated but only identified (e.g., RnF 2 ) by radiotracer technique. No true compounds of Ar, Ne or He are yet known.','[{"s": "The compounds of krypton are fewer. Only the difluoride (KrF", "t": "text"}, {"s": "2", "t": "text"}, {"s": ") has been studied in detail. Compounds of radon have not been isolated but only identified (e.g., RnF", "t": "text"}, {"s": "2", "t": "text"}, {"s": ") by radiotracer technique. No true compounds of Ar, Ne or He are yet known.", "t": "text"}]',NULL,NULL,NULL),
(17596,49,689,'paragraph',NULL,'(a) Xenon-fluorine compounds','[{"s": "(a) Xenon-fluorine compounds", "t": "text"}]',NULL,NULL,NULL),
(17597,49,690,'paragraph',NULL,'Xenon forms three binary fluorides, XeF 2 , XeF 4 and XeF 6 by the direct reaction of elements under appropriate experimental conditions.','[{"s": "Xenon forms three binary fluorides, XeF", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "and XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "by the direct reaction of elements under appropriate experimental conditions.", "t": "text"}]',NULL,NULL,NULL),
(17598,49,691,'paragraph',NULL,'Xe (g) + F 2 (g) P_Block_Elements_Group_15_to_18-image60.png XeF 2 (s)','[{"s": "Xe (g) + F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g)", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image60.png", "t": "img", "alt": ""}, {"s": "XeF", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(s)", "t": "text"}]',NULL,NULL,NULL),
(17599,49,692,'paragraph',NULL,'(xenon in excess)','[{"s": "(xenon in excess)", "t": "text"}]',NULL,NULL,NULL),
(17600,49,693,'paragraph',NULL,'Xe (g) + 2F 2 (g) P_Block_Elements_Group_15_to_18-image79.png XeF 4 (s)','[{"s": "Xe (g) + 2F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g)", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image79.png", "t": "img", "alt": ""}, {"s": "XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(s)", "t": "text"}]',NULL,NULL,NULL),
(17601,49,694,'paragraph',NULL,'(1:5 ratio)','[{"s": "(1:5 ratio)", "t": "text"}]',NULL,NULL,NULL),
(17602,49,695,'paragraph',NULL,'Xe (g) + 3F 2 (g) P_Block_Elements_Group_15_to_18-image99.png XeF 6 (s)','[{"s": "Xe (g) + 3F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g)", "t": "text"}, {"s": "P_Block_Elements_Group_15_to_18-image99.png", "t": "img", "alt": ""}, {"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "(s)", "t": "text"}]',NULL,NULL,NULL),
(17603,49,696,'paragraph',NULL,'(1:20 ratio)','[{"s": "(1:20 ratio)", "t": "text"}]',NULL,NULL,NULL),
(17604,49,697,'paragraph',NULL,'XeF 6 can also be prepared by the interaction of XeF 4 and O 2 F 2 at 143K.','[{"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "can also be prepared by the interaction of XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "and O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "at 143K.", "t": "text"}]',NULL,NULL,NULL),
(17605,49,698,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/chemistry/images/P_Block_Elements_Group_15_to_18-image72.png'),
(17606,49,699,'paragraph',NULL,'XeF 2 , XeF 4 and XeF 6 are colourless crystalline solids and sublime readily at 298 K. They are powerful fluorinating agents. They are readily hydrolysed even by traces of water. For example, XeF 2 is hydrolysed to give Xe, HF and O 2 .','[{"s": "XeF", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "and XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "are colourless crystalline solids and sublime readily at 298 K. They are powerful fluorinating agents. They are readily hydrolysed even by traces of water. For example, XeF", "t": "text"}, {"s": "2", "t": "text"}, {"s": "is hydrolysed to give Xe, HF and O", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17607,49,700,'paragraph',NULL,'2XeF 2 (s) + 2H 2 O(l) → 2Xe (g) + 4 HF(aq) + O 2 (g)','[{"s": "2XeF", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(s) + 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O(l) → 2Xe (g) + 4 HF(aq) + O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g)", "t": "text"}]',NULL,NULL,NULL),
(17608,49,701,'paragraph',NULL,'The structures of the three xenon fluorides can be deduced from VSEPR and these are shown in Fig. 7.9. XeF 2 and XeF 4 have linear and square planar structures respectively. 2 XeF 6 has seven electron pairs (6 bonding pairs and one lone pair) and would, thus, have a distorted octahedral structure as found experimentally in the gas phase.','[{"s": "The structures of the three xenon fluorides can be deduced from VSEPR and these are shown in Fig. 7.9. XeF", "t": "hl"}, {"s": "2", "t": "hl"}, {"s": "and XeF", "t": "hl"}, {"s": "4", "t": "hl"}, {"s": "have linear and square planar structures respectively.", "t": "hl"}, {"s": "2", "t": "text"}, {"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "has seven electron pairs (6 bonding pairs and one lone pair) and would, thus, have a distorted octahedral structure as found experimentally in the gas phase.", "t": "text"}]','marked','["214279", "214281"]',NULL),
(17609,49,702,'paragraph',NULL,'Xenon fluorides react with fluoride ion acceptors to form cationic species and fluoride ion donors to form fluoroanions.','[{"s": "Xenon fluorides react with fluoride ion acceptors to form cationic species and fluoride ion donors to form fluoroanions.", "t": "text"}]',NULL,NULL,NULL),
(17610,49,703,'paragraph',NULL,'XeF 2 + PF 5 → [XeF] + [PF 6 ] – ;','[{"s": "XeF", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ PF", "t": "text"}, {"s": "5", "t": "text"}, {"s": "→ [XeF]", "t": "text"}, {"s": "+", "t": "text"}, {"s": "[PF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "]", "t": "text"}, {"s": "–", "t": "text"}, {"s": ";", "t": "text"}]',NULL,NULL,NULL),
(17611,49,704,'paragraph',NULL,'XeF 4 + SbF 5 → [XeF 3 ] + [SbF 6 ] –','[{"s": "XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ SbF", "t": "text"}, {"s": "5", "t": "text"}, {"s": "→ [XeF", "t": "text"}, {"s": "3", "t": "text"}, {"s": "]", "t": "text"}, {"s": "+", "t": "text"}, {"s": "[SbF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "]", "t": "text"}, {"s": "–", "t": "text"}]',NULL,NULL,NULL),
(17612,49,705,'paragraph',NULL,'XeF 6 + MF → M + [XeF 7 ] – (M = Na, K, Rb or Cs)','[{"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "+ MF → M", "t": "text"}, {"s": "+", "t": "text"}, {"s": "[XeF", "t": "text"}, {"s": "7", "t": "text"}, {"s": "]", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(M = Na, K, Rb or Cs)", "t": "text"}]',NULL,NULL,NULL),
(17613,49,706,'paragraph',NULL,'(b) Xenon-oxygen compounds 2','[{"s": "(b) Xenon-oxygen compounds", "t": "hl"}, {"s": "2", "t": "hl"}]','marked','["214279", "214280"]',NULL),
(17614,49,707,'paragraph',NULL,'Hydrolysis of XeF 4 and XeF 6 with water gives Xe0 3 .','[{"s": "Hydrolysis of XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "and XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "with water gives Xe0", "t": "text"}, {"s": "3", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17615,49,708,'paragraph',NULL,'6XeF 4 + 12 H 2 O → 4Xe + 2Xe0 3 + 24 HF + 3 O 2','[{"s": "6XeF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 12 H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O → 4Xe + 2Xe0", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 24 HF + 3 O", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(17616,49,709,'paragraph',NULL,'XeF 6 + 3 H 2 O → XeO 3 + 6 HF','[{"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "+ 3 H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O → XeO", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ 6 HF", "t": "text"}]',NULL,NULL,NULL),
(17617,49,710,'paragraph',NULL,'Partial hydrolysis of XeF 6 gives oxyfluorides, XeOF 4 and XeO 2 F 2 .','[{"s": "Partial hydrolysis of XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "gives oxyfluorides, XeOF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "and XeO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "F", "t": "text"}, {"s": "2", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(17618,49,711,'paragraph',NULL,'XeF 6 + H 2 O → XeOF 4 + 2 HF','[{"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "+ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O → XeOF", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+ 2 HF", "t": "text"}]',NULL,NULL,NULL),
(17619,49,712,'paragraph',NULL,'XeF 6 + 2 H 2 O → XeO 2 F 2 + 4HF','[{"s": "XeF", "t": "text"}, {"s": "6", "t": "text"}, {"s": "+ 2 H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O → XeO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "F", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 4HF", "t": "text"}]',NULL,NULL,NULL),
