(18114,50,469,'paragraph',NULL,'8.8 While sulphur dioxide and hydrogen peroxide can act as oxidising as well as reducing agents in their reactions, ozone and nitric acid act only as oxidants. Why ?','[{"s": "8.8 While sulphur dioxide and hydrogen peroxide can act as oxidising as well as reducing agents in their reactions, ozone and nitric acid act only as oxidants. Why ?", "t": "text"}]',NULL,NULL,NULL),
(18115,50,470,'paragraph',NULL,'8.9 Consider the reactions:','[{"s": "8.9 Consider the reactions:", "t": "text"}]',NULL,NULL,NULL),
(18116,50,471,'paragraph',NULL,'(a) 6 CO 2 (g) + 6H 2 O(l) → C 6 H 12 O 6 (aq) + 6O 2 (g)','[{"s": "(a) 6 CO", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g) + 6H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O(l) → C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "12", "t": "text"}, {"s": "O", "t": "text"}, {"s": "6", "t": "text"}, {"s": "(aq) + 6O", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g)", "t": "text"}]',NULL,NULL,NULL),
