(18149,51,28,'paragraph',NULL,'It can be shown that in a given solution sum of all the mole fractions is unity, i.e.','[{"s": "It can be shown that in a given solution sum of all the mole fractions is unity, i.e.", "t": "text"}]',NULL,NULL,NULL),
(18150,51,29,'paragraph',NULL,'x 1 + x 2 + .................. + x i = 1 (2.7)','[{"s": "x", "t": "text"}, {"s": "1", "t": "text"}, {"s": "+", "t": "text"}, {"s": "x", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ .................. +", "t": "text"}, {"s": "x", "t": "text"}, {"s": "i", "t": "text"}, {"s": "= 1 (2.7)", "t": "text"}]',NULL,NULL,NULL),
(18151,51,30,'paragraph',NULL,'Mole fraction unit is very useful in relating some physical properties of solutions, say vapour pressure with the concentration of the solution and quite useful in describing the calculations involving gas mixtures.','[{"s": "Mole fraction unit is very useful in relating some physical properties of solutions, say vapour pressure with the concentration of the solution and quite useful in describing the calculations involving gas mixtures.", "t": "text"}]',NULL,NULL,NULL),
