(18188,51,67,'paragraph',NULL,'2.1 Calculate the mass percentage of benzene (C 6 H 6 ) and carbon tetrachloride (CCl 4 ) if 22 g of benzene is dissolved in 122 g of carbon tetrachloride.','[{"s": "2.1", "t": "text"}, {"s": "Calculate the mass percentage of benzene (C", "t": "text"}, {"s": "6", "t": "text"}, {"s": "H", "t": "text"}, {"s": "6", "t": "text"}, {"s": ") and carbon tetrachloride (CCl", "t": "text"}, {"s": "4", "t": "text"}, {"s": ") if 22 g of benzene is dissolved in 122 g of carbon tetrachloride.", "t": "text"}]',NULL,NULL,NULL),
(18189,51,68,'paragraph',NULL,'2.2 Calculate the mole fraction of benzene in solution containing 30% by mass in carbon tetrachloride.','[{"s": "2.2", "t": "text"}, {"s": "Calculate the mole fraction of benzene in solution containing 30% by mass in carbon tetrachloride.", "t": "text"}]',NULL,NULL,NULL),
(18190,51,69,'paragraph',NULL,'2.3 Calculate the molarity of each of the following solutions: (a) 30 g of Co(NO 3 ) 2 . 6H 2 O in 4.3 L of solution (b) 30 mL of 0.5 M H 2 SO 4 diluted to 500 mL.','[{"s": "2.3", "t": "text"}, {"s": "Calculate the molarity of each of the following solutions: (a) 30 g of Co(NO", "t": "text"}, {"s": "3", "t": "text"}, {"s": ")", "t": "text"}, {"s": "2", "t": "text"}, {"s": ". 6H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O in 4.3 L of solution (b) 30 mL of 0.5 M H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "SO", "t": "text"}, {"s": "4", "t": "text"}, {"s": "diluted to 500 mL.", "t": "text"}]',NULL,NULL,NULL),
