(18332,51,211,'paragraph',NULL,'Solutions-image44.png = Solutions-image99.png (2.27)','[{"s": "Solutions-image44.png", "t": "img", "alt": ""}, {"s": "=", "t": "text"}, {"s": "Solutions-image99.png", "t": "img", "alt": ""}, {"s": "(2.27)", "t": "text"}]',NULL,NULL,NULL),
(18333,51,212,'paragraph',NULL,'or Solutions-image41.png = Solutions-image101.png (2.28)','[{"s": "or", "t": "text"}, {"s": "Solutions-image41.png", "t": "img", "alt": ""}, {"s": "=", "t": "text"}, {"s": "Solutions-image101.png", "t": "img", "alt": ""}, {"s": "(2.28)", "t": "text"}]',NULL,NULL,NULL),
(18334,51,213,'paragraph',NULL,'Here w 1 and w 2 are the masses and M 1 and M 2 are the molar masses of the solvent and solute respectively.','[{"s": "Here w", "t": "text"}, {"s": "1", "t": "text"}, {"s": "and w", "t": "text"}, {"s": "2", "t": "text"}, {"s": "are the masses and M", "t": "text"}, {"s": "1", "t": "text"}, {"s": "and M", "t": "text"}, {"s": "2", "t": "text"}, {"s": "are the molar masses of the solvent and solute respectively.", "t": "text"}]',NULL,NULL,NULL),
(18335,51,214,'paragraph',NULL,'From this equation (2.28), knowing all other quantities, the molar mass of solute (M 2 ) can be calculated.','[{"s": "From this equation (2.28), knowing all other quantities, the molar mass of solute (M", "t": "text"}, {"s": "2", "t": "text"}, {"s": ") can be calculated.", "t": "text"}]',NULL,NULL,NULL),
