(18977,51,856,'paragraph',NULL,'In the following questions a statement of assertion (A) followed by a statement of reason (R) is given. Choose the correct answer out of the following choices.','[{"s": "In the following questions a statement of assertion (A) followed by a statement of reason (R) is given. Choose the correct answer out of the following choices.", "t": "text"}]',NULL,NULL,NULL),
(18978,51,857,'paragraph',NULL,'(a) Assertion and reason both are correct statements and reason is correct explanation for assertion.','[{"s": "(a) Assertion and reason both are correct statements and reason is correct explanation for assertion.", "t": "text"}]',NULL,NULL,NULL),
(18979,51,858,'paragraph',NULL,'(b) Assertion and reason both are correct statements but reason is not correct explanation for assertion.','[{"s": "(b) Assertion and reason both are correct statements but reason is not correct explanation for assertion.", "t": "text"}]',NULL,NULL,NULL),
(18980,51,859,'paragraph',NULL,'(c) Assertion is correct statement but reason is wrong statement.','[{"s": "(c) Assertion is correct statement but reason is wrong statement.", "t": "text"}]',NULL,NULL,NULL),
(18981,51,860,'paragraph',NULL,'(d) Assertion and reason both are incorrect statements.','[{"s": "(d) Assertion and reason both are incorrect statements.", "t": "text"}]',NULL,NULL,NULL),
