(18983,51,862,'paragraph',NULL,'51. Assertion (A) Molarity of a solution in liquid state changes with temperature.','[{"s": "51. Assertion (A) Molarity of a solution in liquid state changes with temperature.", "t": "text"}]',NULL,NULL,NULL),
(18984,51,863,'paragraph',NULL,'Reason (R) The volume of a solution changes with change in temperature.','[{"s": "Reason (R) The volume of a solution changes with change in temperature.", "t": "text"}]',NULL,NULL,NULL),
(18985,51,864,'paragraph',NULL,'52. Assertion (A) When methyl alcohol is added to water, boiling point of water increases.','[{"s": "52. Assertion (A) When methyl alcohol is added to water, boiling point of water increases.", "t": "text"}]',NULL,NULL,NULL),
(18986,51,865,'paragraph',NULL,'Reason (R) When a volatile solute is added to a volatile solvent elevation in boiling point is observed.','[{"s": "Reason (R) When a volatile solute is added to a volatile solvent elevation in boiling point is observed.", "t": "text"}]',NULL,NULL,NULL),
(18987,51,866,'paragraph',NULL,'53. Assertion (A) When NaCl is added to water a depression in freezing point is observed.','[{"s": "53. Assertion (A) When NaCl is added to water a depression in freezing point is observed.", "t": "text"}]',NULL,NULL,NULL),
(18988,51,867,'paragraph',NULL,'Reason (R) The lowering of vapour pressure of a solution causes depression in the freezing point.','[{"s": "Reason (R) The lowering of vapour pressure of a solution causes depression in the freezing point.", "t": "text"}]',NULL,NULL,NULL),
(18989,51,868,'paragraph',NULL,'54. Assertion (A) When a solution is separated from the pure solvent by a semipermeable membrane, the solvent molecules pass through it from pure solvent side to the solution side.','[{"s": "54. Assertion (A) When a solution is separated from the pure solvent by a semipermeable membrane, the solvent molecules pass through it from pure solvent side to the solution side.", "t": "text"}]',NULL,NULL,NULL),
