(19179,52,166,'paragraph',NULL,'How many seconds are there in 2 days?','[{"s": "How many seconds are there in 2 days?", "t": "text"}]',NULL,NULL,NULL),
(19180,52,167,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(19181,52,168,'paragraph',NULL,'Here, we know 1 day = 24 hours (h)','[{"s": "Here, we know 1 day = 24 hours (h)", "t": "text"}]',NULL,NULL,NULL),
(19182,52,169,'paragraph',NULL,'or Some_Basic_Concept_of_Chemistry-image49.png','[{"s": "or", "t": "text"}, {"s": "Some_Basic_Concept_of_Chemistry-image49.png", "t": "img", "alt": ""}]',NULL,NULL,NULL),
(19183,52,170,'paragraph',NULL,'then, 1h = 60 min','[{"s": "then, 1h = 60 min", "t": "text"}]',NULL,NULL,NULL),
