(20072,53,247,'paragraph',NULL,'= 6.626 × 10 -19 J','[{"s": "= 6.626 × 10", "t": "text"}, {"s": "-19", "t": "text"}, {"s": "J", "t": "text"}]',NULL,NULL,NULL),
(20073,53,248,'paragraph',NULL,'The energy of one mole of photons','[{"s": "The energy of one mole of photons", "t": "text"}]',NULL,NULL,NULL),
(20074,53,249,'paragraph',NULL,'= 6.626 ×10 –19 J × 6.022 ×10 23 mol –1','[{"s": "= 6.626 ×10", "t": "text"}, {"s": "–19", "t": "text"}, {"s": "J × 6.022 ×10", "t": "text"}, {"s": "23", "t": "text"}, {"s": "mol", "t": "text"}, {"s": "–1", "t": "text"}]',NULL,NULL,NULL),
(20075,53,250,'paragraph',NULL,'= 3.99 × 10 5 J mol –1','[{"s": "= 3.99 × 10", "t": "text"}, {"s": "5", "t": "text"}, {"s": "J mol", "t": "text"}, {"s": "–1", "t": "text"}]',NULL,NULL,NULL),
(20076,53,251,'paragraph',NULL,'The minimum energy needed to remove one mole of electrons from sodium','[{"s": "The minimum energy needed to remove one mole of electrons from sodium", "t": "text"}]',NULL,NULL,NULL),
(20077,53,252,'paragraph',NULL,'= (3.99 –1.68) 10 5 J mol = 2.31 × 10 5 J mol –1','[{"s": "= (3.99 –1.68) 10", "t": "text"}, {"s": "5", "t": "text"}, {"s": "J mol", "t": "text"}, {"s": "", "t": "br"}, {"s": "= 2.31 × 10", "t": "text"}, {"s": "5", "t": "text"}, {"s": "J mol", "t": "text"}, {"s": "–1", "t": "text"}]',NULL,NULL,NULL),
(20078,53,253,'paragraph',NULL,'The minimum energy for one electron','[{"s": "The minimum energy for one electron", "t": "text"}]',NULL,NULL,NULL),
