(20573,54,211,'paragraph',NULL,'(Here, negative sign indicates the exothermic nature of the reaction)','[{"s": "(Here, negative sign indicates the exothermic nature of the reaction)", "t": "text"}]',NULL,NULL,NULL),
(20574,54,212,'paragraph',NULL,'Thus, ∆U for the combustion of the 1g of graphite = – 20.7 kJK–1','[{"s": "Thus, ∆U for the combustion of the 1g of graphite = – 20.7 kJK–1", "t": "text"}]',NULL,NULL,NULL),
(20575,54,213,'paragraph',NULL,'For combustion of 1 mol of graphite,','[{"s": "For combustion of 1 mol of graphite,", "t": "text"}]',NULL,NULL,NULL),
