(20580,54,218,'paragraph',NULL,'In a chemical reaction, reactants are converted into products and is represented by,','[{"s": "In a chemical reaction, reactants are converted into products and is represented by,", "t": "text"}]',NULL,NULL,NULL),
(20581,54,219,'paragraph',NULL,'Reactants → Products','[{"s": "Reactants → Products", "t": "text"}]',NULL,NULL,NULL),
(20582,54,220,'paragraph',NULL,'The enthalpy change accompanying a reaction is called the reaction enthalpy . The enthalpy change of a chemical reaction, is given by the symbol ∆ r H','[{"s": "The enthalpy change accompanying a reaction is called the", "t": "text"}, {"s": "reaction enthalpy", "t": "text"}, {"s": ". The enthalpy change of a chemical reaction, is given by the symbol ∆", "t": "text"}, {"s": "r", "t": "text"}, {"s": "H", "t": "text"}]',NULL,NULL,NULL),
(20583,54,221,'paragraph',NULL,'∆ r H = (sum of enthalpies of products) – (sum of enthalpies of reactants)','[{"s": "∆", "t": "text"}, {"s": "r", "t": "text"}, {"s": "H = (sum of enthalpies of products) – (sum of enthalpies of reactants)", "t": "text"}]',NULL,NULL,NULL),
