(20998,54,636,'paragraph',NULL,'Calculate ∆ r G ⊖ for conversion of oxygen to ozone, 3/2 O2(g) → O3(g) at 298 K. if K p for this conversion is 2.47 × 10–29.','[{"s": "Calculate ∆", "t": "text"}, {"s": "r", "t": "text"}, {"s": "G", "t": "text"}, {"s": "⊖", "t": "text"}, {"s": "for conversion of oxygen to ozone, 3/2 O2(g) → O3(g) at 298 K. if K", "t": "text"}, {"s": "p", "t": "text"}, {"s": "for this conversion is 2.47 × 10–29.", "t": "text"}]',NULL,NULL,NULL),
(20999,54,637,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
