(21161,55,131,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Alternating_Current-image126.png'),
(21162,55,132,'paragraph',NULL,'Figure 7.8 An ac source connected to a capacitor.','[{"s": "Figure 7.8 An ac source connected to a capacitor.", "t": "text"}]',NULL,NULL,NULL),
