(21195,55,165,'paragraph',NULL,'This current oscillates between +1.47A and –1.47 A, and is ahead of the voltage by π/2.','[{"s": "This current oscillates between +1.47A and –1.47 A, and is ahead of the voltage by π/2.", "t": "text"}]',NULL,NULL,NULL),
(21196,55,166,'paragraph',NULL,'If the frequency is doubled, the capacitive reactance is halved and consequently, the current is doubled.','[{"s": "If the frequency is doubled, the capacitive reactance is halved and consequently, the current is doubled.", "t": "text"}]',NULL,NULL,NULL),
(21197,55,167,'paragraph',NULL,'Example 7.5 A light bulb and an open coil inductor are connected to an ac source through a key as shown in Fig. 7.11.','[{"s": "Example 7.5 A light bulb and an open coil inductor are connected to an ac source through a key as shown in Fig. 7.11.", "t": "text"}]',NULL,NULL,NULL),
