(24145,61,157,'paragraph',NULL,'Figure 2.10 Equipotential surfaces for a uniform electric field.','[{"s": "Figure 2.10 Equipotential surfaces for a uniform electric field.", "t": "text"}]',NULL,NULL,NULL),
(21326,55,296,'paragraph',NULL,'ω 0 L(1+ Δωω 0 )− 1ω 0 C(1+ Δωω0 ) =R','[{"s": "ω", "t": "text"}, {"s": "0", "t": "text"}, {"s": "L(1+", "t": "text"}, {"s": "Δωω", "t": "text"}, {"s": "0", "t": "text"}, {"s": ")−", "t": "text"}, {"s": "1ω", "t": "text"}, {"s": "0", "t": "text"}, {"s": "C(1+", "t": "text"}, {"s": "Δωω0", "t": "text"}, {"s": ")", "t": "text"}, {"s": "=R", "t": "text"}]',NULL,NULL,NULL),
