(21328,55,298,'paragraph',NULL,'ω 0 L(1+ Δω/ω 0 )− ω 0 L(1+ Δω/ω0 ) =R','[{"s": "ω", "t": "text"}, {"s": "0", "t": "text"}, {"s": "L(1+", "t": "text"}, {"s": "Δω/ω", "t": "text"}, {"s": "0", "t": "text"}, {"s": ")−", "t": "text"}, {"s": "ω", "t": "text"}, {"s": "0", "t": "text"}, {"s": "L(1+", "t": "text"}, {"s": "Δω/ω0", "t": "text"}, {"s": ")", "t": "text"}, {"s": "=R", "t": "text"}]',NULL,NULL,NULL),
(21329,55,299,'paragraph',NULL,'We can approximate (1+ Δωω 0 ) −1 as (1− Δωω 0 )','[{"s": "We can approximate", "t": "text"}, {"s": "(1+", "t": "text"}, {"s": "Δωω", "t": "text"}, {"s": "0", "t": "text"}, {"s": ")", "t": "text"}, {"s": "−1", "t": "text"}, {"s": "as (1−", "t": "text"}, {"s": "Δωω", "t": "text"}, {"s": "0", "t": "text"}, {"s": ")", "t": "text"}]',NULL,NULL,NULL),
