(21682,55,652,'paragraph',NULL,'Q. 10. Electrical energy is transmitted over large distances at high alternating voltages. Which of the following statements is (are) correct?','[{"s": "Q. 10. Electrical energy is transmitted over large distances at high alternating voltages. Which of the following statements is (are) correct?", "t": "text"}]',NULL,NULL,NULL),
(21683,55,653,'paragraph',NULL,'(a) For a given power level, there is a lower current','[{"s": "(a) For a given power level, there is a lower current", "t": "text"}]',NULL,NULL,NULL),
(21684,55,654,'paragraph',NULL,'(b) Lower current implies less power loss','[{"s": "(b) Lower current implies less power loss", "t": "text"}]',NULL,NULL,NULL),
(21685,55,655,'paragraph',NULL,'(c) Transmission lines can be made thinner','[{"s": "(c) Transmission lines can be made thinner", "t": "text"}]',NULL,NULL,NULL),
