(21731,55,701,'paragraph',NULL,'Q. 30. For an L-C-R circuit driven at a frequency ω , the equation reads','[{"s": "Q. 30. For an L-C-R circuit driven at a frequency", "t": "text"}, {"s": "ω", "t": "text"}, {"s": ", the equation reads", "t": "text"}]',NULL,NULL,NULL),
(21732,55,702,'paragraph',NULL,'L di/dt + Ri + qC = V i = V m sin ωt','[{"s": "L", "t": "text"}, {"s": "di/dt", "t": "text"}, {"s": "+ Ri +", "t": "text"}, {"s": "qC", "t": "text"}, {"s": "= V", "t": "text"}, {"s": "i", "t": "text"}, {"s": "= V", "t": "text"}, {"s": "m", "t": "text"}, {"s": "sin ωt", "t": "text"}]',NULL,NULL,NULL),
(21733,55,703,'paragraph',NULL,'(a) Multiply the equation by i and simplify where possible.','[{"s": "(a) Multiply the equation by i and simplify where possible.", "t": "text"}]',NULL,NULL,NULL),
