(21805,56,63,'paragraph',NULL,'= 5.3 × 10 –11 m.','[{"s": "= 5.3 × 10", "t": "text"}, {"s": "–11", "t": "text"}, {"s": "m.", "t": "text"}]',NULL,NULL,NULL),
(21806,56,64,'paragraph',NULL,'The velocity of the revolving electron can be computed from Eq. (12.3) with m = 9.1 × 10 –31 kg,','[{"s": "The velocity of the revolving electron can be computed from Eq. (12.3) with m = 9.1 × 10", "t": "text"}, {"s": "–31", "t": "text"}, {"s": "kg,", "t": "text"}]',NULL,NULL,NULL),
