(22200,57,84,'paragraph',NULL,'= 8.5 × 10 28 m –3','[{"s": "= 8.5 × 10", "t": "text"}, {"s": "28", "t": "text"}, {"s": "m", "t": "text"}, {"s": "–3", "t": "text"}]',NULL,NULL,NULL),
