(22340,57,224,'paragraph',NULL,'Figure 3.16 Parallel combination of three resistors R 1 , R 2 and R 3 .','[{"s": "Figure 3.16 Parallel combination of three resistors R", "t": "text"}, {"s": "1", "t": "text"}, {"s": ", R", "t": "text"}, {"s": "2", "t": "text"}, {"s": "and R", "t": "text"}, {"s": "3", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(22341,57,225,'paragraph',NULL,'Exactly as before','[{"s": "Exactly as before", "t": "text"}]',NULL,NULL,NULL),
(22342,57,226,'paragraph',NULL,'I = I 1 + I 2 + I 3 (3.46)','[{"s": "I = I", "t": "text"}, {"s": "1", "t": "text"}, {"s": "+ I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ I", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(3.46)", "t": "text"}]',NULL,NULL,NULL),
(22343,57,227,'paragraph',NULL,'and applying Ohm’s law to R 1 , R 2 and R 3 we get,','[{"s": "and applying Ohm’s law to", "t": "text"}, {"s": "R", "t": "text"}, {"s": "1", "t": "text"}, {"s": ",", "t": "text"}, {"s": "R", "t": "text"}, {"s": "2", "t": "text"}, {"s": "and", "t": "text"}, {"s": "R", "t": "text"}, {"s": "3", "t": "text"}, {"s": "we get,", "t": "text"}]',NULL,NULL,NULL),
(22344,57,228,'paragraph',NULL,'V = I 1 R 1 , V = I 2 R 2 , V = I 3 R 3 (3.47)','[{"s": "V = I", "t": "text"}, {"s": "1", "t": "text"}, {"s": "R", "t": "text"}, {"s": "1", "t": "text"}, {"s": ", V = I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "R", "t": "text"}, {"s": "2", "t": "text"}, {"s": ", V = I", "t": "text"}, {"s": "3", "t": "text"}, {"s": "R", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(3.47)", "t": "text"}]',NULL,NULL,NULL),
(22345,57,229,'paragraph',NULL,'So that','[{"s": "So that", "t": "text"}]',NULL,NULL,NULL),
