(22530,57,414,'paragraph',NULL,'or 20I 1 + 3I g – 12I 2 = 0 [3.84(a)]','[{"s": "or 20I", "t": "text"}, {"s": "1", "t": "text"}, {"s": "+ 3I", "t": "text"}, {"s": "g", "t": "text"}, {"s": "– 12I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "= 0 [3.84(a)]", "t": "text"}]',NULL,NULL,NULL),
