(22533,57,417,'paragraph',NULL,'10I 1 – 30I g –5I 2 = 0','[{"s": "10I", "t": "text"}, {"s": "1", "t": "text"}, {"s": "– 30I", "t": "text"}, {"s": "g", "t": "text"}, {"s": "–5I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "= 0", "t": "text"}]',NULL,NULL,NULL),
(22534,57,418,'paragraph',NULL,'2I 1 – 6I g – I 2 = 0 [3.84(b)]','[{"s": "2I", "t": "text"}, {"s": "1", "t": "text"}, {"s": "– 6I", "t": "text"}, {"s": "g", "t": "text"}, {"s": "– I", "t": "text"}, {"s": "2", "t": "text"}, {"s": "= 0 [3.84(b)]", "t": "text"}]',NULL,NULL,NULL),
(22535,57,419,'paragraph',NULL,'Considering the mesh ADCEA,','[{"s": "Considering the mesh ADCEA,", "t": "text"}]',NULL,NULL,NULL),
