(22561,57,445,'paragraph',NULL,'After S is connected in parallel with a resistance of 12Ω , the resistance across the gap changes from Sto Seq, where','[{"s": "After S is connected in parallel with a resistance of 12Ω , the resistance across the gap changes from Sto Seq, where", "t": "text"}]',NULL,NULL,NULL),
(22562,57,446,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Current_Electricity-image84.png'),
(22563,57,447,'paragraph',NULL,'and hence the new balance condition now gives','[{"s": "and hence the new balance condition now gives", "t": "text"}]',NULL,NULL,NULL),
