(23316,59,138,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Electromagnetic_Induction-image53.png'),
(23317,59,139,'paragraph',NULL,'Note that we have used v = ω r. This gives','[{"s": "Note that we have used v = ω r. This gives", "t": "text"}]',NULL,NULL,NULL),
