(23413,59,235,'paragraph',NULL,'Thus, the self-induced emf always opposes any change (increase or decrease) of current in the coil.','[{"s": "Thus, the self-induced emf always opposes any change (increase or decrease) of current in the coil.", "t": "text"}]',NULL,NULL,NULL),
(23414,59,236,'paragraph',NULL,'0 n I (neglecting edge effects, as before). The total flux linked with the solenoid is','[{"s": "", "t": "br"}, {"s": "0", "t": "text"}, {"s": "n I (neglecting edge effects, as before). The total flux linked with the solenoid is", "t": "text"}]',NULL,NULL,NULL),
