(23416,59,238,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Electromagnetic_Induction-image9.png'),
(23418,59,240,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Electromagnetic_Induction-image99.png'),
(23419,59,241,'paragraph',NULL,'Electromagnetic_Induction-image19.png (6.17)','[{"s": "Electromagnetic_Induction-image19.png", "t": "img", "alt": ""}, {"s": "(6.17)", "t": "text"}]',NULL,NULL,NULL),
(23420,59,242,'paragraph',NULL,'If we fill the inside of the solenoid with a material of relative permeability µ r (for example soft iron, which has a high value of relative permeability), then,','[{"s": "If we fill the inside of the solenoid with a material of relative permeability µ", "t": "text"}, {"s": "r", "t": "text"}, {"s": "(for example soft iron, which has a high value of relative permeability), then,", "t": "text"}]',NULL,NULL,NULL),
(23421,59,243,'paragraph',NULL,'Electromagnetic_Induction-image86.png (6.18)','[{"s": "Electromagnetic_Induction-image86.png", "t": "img", "alt": ""}, {"s": "(6.18)", "t": "text"}]',NULL,NULL,NULL),
(23422,59,244,'paragraph',NULL,'The self-inductance of the coil depends on its geometry and on the permeability of the medium.','[{"s": "The self-inductance of the coil depends on its geometry and on the permeability of the medium.", "t": "text"}]',NULL,NULL,NULL),
