(24436,61,448,'paragraph',NULL,'W=∫ Q 0 Q\'/CδQ\'=1/C[Q \'2 2] Q 0 =Q2/2C','[{"s": "W=∫", "t": "text"}, {"s": "Q", "t": "text"}, {"s": "0", "t": "text"}, {"s": "Q\'/CδQ\'=1/C[Q", "t": "text"}, {"s": "\'2", "t": "text"}, {"s": "2]", "t": "text"}, {"s": "Q", "t": "text"}, {"s": "0", "t": "text"}, {"s": "=Q2/2C", "t": "text"}]',NULL,NULL,NULL),
