(25021,62,271,'paragraph',NULL,'= 6.48 × 10 23 kg.','[{"s": "= 6.48 × 10", "t": "text"}, {"s": "23", "t": "text"}, {"s": "kg.", "t": "text"}]',NULL,NULL,NULL),
(25022,62,272,'paragraph',NULL,'(ii) Once again Kepler’s third law comes to our aid,','[{"s": "(ii) Once again Kepler’s third law comes to our aid,", "t": "text"}]',NULL,NULL,NULL),
