(25703,64,143,'paragraph',NULL,'Impulse is the change in momentum vector. Therefore,','[{"s": "Impulse is the change in momentum vector. Therefore,", "t": "text"}]',NULL,NULL,NULL),
(25704,64,144,'paragraph',NULL,'x -component of impulse = – 2 m u','[{"s": "x", "t": "text"}, {"s": "-component of impulse = – 2", "t": "text"}, {"s": "m u", "t": "text"}]',NULL,NULL,NULL),
