(25722,64,162,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Laws_of_Motion-image11.png'),
(25723,64,163,'paragraph',NULL,'(where we have taken a common interval of time for both forces i.e. the time for which the two bodies are in contact.)','[{"s": "(where we have taken a common interval of time for both forces i.e. the time for which the two bodies are in contact.)", "t": "text"}]',NULL,NULL,NULL),
(25724,64,164,'paragraph',NULL,'Since Laws_of_Motion-image12.png by the third law,','[{"s": "Since", "t": "text"}, {"s": "Laws_of_Motion-image12.png", "t": "img", "alt": ""}, {"s": "by the third law,", "t": "text"}]',NULL,NULL,NULL),
