(25738,64,178,'paragraph',NULL,'Equation (5.11) implies that','[{"s": "Equation (5.11) implies that", "t": "text"}]',NULL,NULL,NULL),
(25739,64,179,'paragraph',NULL,'F 1x + F 2x + F 3x = 0','[{"s": "F", "t": "text"}, {"s": "1x", "t": "text"}, {"s": "+ F", "t": "text"}, {"s": "2x", "t": "text"}, {"s": "+ F", "t": "text"}, {"s": "3x", "t": "text"}, {"s": "=", "t": "text"}, {"s": "0", "t": "text"}]',NULL,NULL,NULL),
