(25800,64,240,'paragraph',NULL,'Apply the second law to motion of the trolley (Fig. 5.12(c)),','[{"s": "Apply the second law to motion of the trolley (Fig. 5.12(c)),", "t": "text"}]',NULL,NULL,NULL),
(25801,64,241,'paragraph',NULL,'T – f k = 20 a .','[{"s": "T", "t": "text"}, {"s": "–", "t": "text"}, {"s": "f", "t": "text"}, {"s": "k", "t": "text"}, {"s": "= 20", "t": "text"}, {"s": "a", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
