(26263,65,325,'paragraph',NULL,'(a) the force on it is zero,','[{"s": "(a) the force on it is zero,", "t": "text"}]',NULL,NULL,NULL),
(26264,65,326,'paragraph',NULL,'(b) the torque on it is m × B,','[{"s": "(b) the torque on it is m × B,", "t": "text"}]',NULL,NULL,NULL),
(26265,65,327,'paragraph',NULL,'(c) its potential energy is –m.B, where we choose the zero of energy at the orientation when m is perpendicular to B.','[{"s": "(c) its potential energy is –m.B, where we choose the zero of energy at the orientation when m is perpendicular to B.", "t": "text"}]',NULL,NULL,NULL),
(26266,65,328,'paragraph',NULL,'3. Consider a bar magnet of size l and magnetic moment m, at a distance r from its mid-point, where r>>l, the magnetic field B due to this bar is,','[{"s": "3. Consider a bar magnet of size l and magnetic moment m, at a distance r from its mid-point, where r>>l, the magnetic field B due to this bar is,", "t": "text"}]',NULL,NULL,NULL),
(26267,65,329,'paragraph',NULL,'Magnetism_and_Matter-image23.png (along axis)','[{"s": "Magnetism_and_Matter-image23.png", "t": "img", "alt": ""}, {"s": "(along axis)", "t": "text"}]',NULL,NULL,NULL),
