(26301,65,363,'paragraph',NULL,'Exercises','[{"s": "Exercises", "t": "text"}]',NULL,NULL,NULL),
(26302,65,364,'paragraph',NULL,'5.1 Answer the following questions regarding the earth’s magnetism:','[{"s": "5.1 Answer the following questions regarding the earth’s magnetism:", "t": "text"}]',NULL,NULL,NULL),
(26303,65,365,'paragraph',NULL,'(a) A vector needs three quantities for its specification. Name the three independent quantities conventionally used to specify the earth’s magnetic field.','[{"s": "(a) A vector needs three quantities for its specification. Name the three independent quantities conventionally used to specify the earth’s magnetic field.", "t": "text"}]',NULL,NULL,NULL),
(26304,65,366,'paragraph',NULL,'(b) The angle of dip at a location in southern India is about 18°. Would you expect a greater or smaller dip angle in Britain?','[{"s": "(b) The angle of dip at a location in southern India is about 18°. Would you expect a greater or smaller dip angle in Britain?", "t": "text"}]',NULL,NULL,NULL),
