(27445,68,152,'paragraph',NULL,'(4.23a)','[{"s": "(4.23a)", "t": "text"}]',NULL,NULL,NULL),
(27446,68,153,'paragraph',NULL,'then, a vector T = a + b – c has components :','[{"s": "then, a vector", "t": "text"}, {"s": "T", "t": "text"}, {"s": "=", "t": "text"}, {"s": "a", "t": "text"}, {"s": "+", "t": "text"}, {"s": "b", "t": "text"}, {"s": "–", "t": "text"}, {"s": "c", "t": "text"}, {"s": "has components :", "t": "text"}]',NULL,NULL,NULL),
