(27505,68,212,'paragraph',NULL,'Suppose a particle moves along the curve shown by the thick line and is at P at time t and P′ at time t′ [Fig. 4.12(b)]. Then, the displacement is :','[{"s": "Suppose a particle moves along the curve shown by the thick line and is at P at time t and P′ at time t′ [Fig. 4.12(b)]. Then, the displacement is :", "t": "text"}]',NULL,NULL,NULL),
(27506,68,213,'paragraph',NULL,'∆ r = r ′ – r (4.25)','[{"s": "∆", "t": "text"}, {"s": "r", "t": "text"}, {"s": "=", "t": "text"}, {"s": "r", "t": "text"}, {"s": "′ –", "t": "text"}, {"s": "r", "t": "text"}, {"s": "(4.25)", "t": "text"}]',NULL,NULL,NULL),
