(27511,68,218,'heading',4,'Velocity',NULL,NULL,NULL,NULL),
(27512,68,219,'paragraph',NULL,'The average velocity Motion_in_a_Plane-image59.png of an object is the ratio of the displacement and the corresponding time interval :','[{"s": "The average velocity", "t": "text"}, {"s": "Motion_in_a_Plane-image59.png", "t": "img", "alt": "69"}, {"s": "of an object is the ratio of the displacement and the corresponding time interval :", "t": "text"}]',NULL,NULL,NULL),
