(27742,68,449,'paragraph',NULL,'Therefore,','[{"s": "Therefore,", "t": "text"}]',NULL,NULL,NULL),
(27743,68,450,'image',NULL,'Screen Shot 2019-06-08 at 6.09.50 PM',NULL,NULL,NULL,'/ncert/physics/images/Motion_in_a_Plane-image118.png'),
(27744,68,451,'paragraph',NULL,'If ∆t is small, ∆θ will also be small and then arc PP′ can be approximately taken to be|∆ r |:','[{"s": "If ∆t is small, ∆θ will also be small and then arc PP′ can be approximately taken to be|∆", "t": "text"}, {"s": "r", "t": "text"}, {"s": "|:", "t": "text"}]',NULL,NULL,NULL),
