(27746,68,453,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Motion_in_a_Plane-image108.png'),
(27747,68,454,'paragraph',NULL,'Or,','[{"s": "Or,", "t": "text"}]',NULL,NULL,NULL),
(27748,68,455,'image',NULL,'Screen Shot 2019-06-08 at 6.10.38 PM',NULL,NULL,NULL,'/ncert/physics/images/Motion_in_a_Plane-image106.png'),
(27749,68,456,'paragraph',NULL,'Therefore, the centripetal acceleration a c is :','[{"s": "Therefore, the centripetal acceleration a", "t": "text"}, {"s": "c", "t": "text"}, {"s": "is :", "t": "text"}]',NULL,NULL,NULL),
(27750,68,457,'image',NULL,'Screen Shot 2019-06-08 at 6.11.15 PM',NULL,NULL,NULL,'/ncert/physics/images/Motion_in_a_Plane-image112.png'),
(27751,68,458,'paragraph',NULL,'(4.44)','[{"s": "(4.44)", "t": "text"}]',NULL,NULL,NULL),
