(28939,71,72,'paragraph',NULL,'To convert it into energy units, we multiply it by c 2 and find that','[{"s": "To convert it into energy units, we multiply it by c", "t": "text"}, {"s": "2", "t": "text"}, {"s": "and find that", "t": "text"}]',NULL,NULL,NULL),
(28940,71,73,'paragraph',NULL,'energy equivalent = 1.6605 × 10 –27 × (2.9979 × 10 8 ) 2 kg m 2 /s 2','[{"s": "energy equivalent = 1.6605 × 10", "t": "text"}, {"s": "–27", "t": "text"}, {"s": "× (2.9979 × 10", "t": "text"}, {"s": "8", "t": "text"}, {"s": ")", "t": "text"}, {"s": "2", "t": "text"}, {"s": "kg m", "t": "text"}, {"s": "2", "t": "text"}, {"s": "/s", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
