(29553,72,161,'heading',4,'14.5 Velocity and acceleration in simple harmonic motion',NULL,NULL,NULL,NULL),
(29555,72,163,'paragraph',NULL,'v = ω A (14.8)','[{"s": "v = ω A (14.8)", "t": "text"}]',NULL,NULL,NULL),
