(29564,72,172,'paragraph',NULL,'a (t) = –ω 2 A cos (ωt + φ)','[{"s": "a (t) = –ω", "t": "text"}, {"s": "2", "t": "text"}, {"s": "A cos (ωt + φ)", "t": "text"}]',NULL,NULL,NULL),
