(30267,73,325,'paragraph',NULL,'or v 3 = 30 cm','[{"s": "or v", "t": "text"}, {"s": "3", "t": "text"}, {"s": "= 30 cm", "t": "text"}]',NULL,NULL,NULL),
(30268,73,326,'paragraph',NULL,'The final image is formed 30 cm to the right of the third lens.','[{"s": "The final image is formed 30 cm to the right of the third lens.", "t": "text"}]',NULL,NULL,NULL),
