(30280,73,338,'paragraph',NULL,'δ = i + e – A (9.35)','[{"s": "δ =", "t": "text"}, {"s": "i", "t": "text"}, {"s": "+", "t": "text"}, {"s": "e", "t": "text"}, {"s": "–", "t": "text"}, {"s": "A", "t": "text"}, {"s": "(9.35)", "t": "text"}]',NULL,NULL,NULL),
