(30282,73,340,'paragraph',NULL,'Figure 9.23 A ray of light passing through a triangular glass prism.','[{"s": "Figure 9.23 A ray of light passing through a triangular glass prism.", "t": "text"}]',NULL,NULL,NULL),
(30283,73,341,'paragraph',NULL,'Thus, the angle of deviation depends on the angle of incidence.','[{"s": "Thus, the angle of deviation depends on the angle of incidence.", "t": "text"}]',NULL,NULL,NULL),
