(31036,74,414,'paragraph',NULL,'• For t ≤ t 1 ; A = 0, B = 0; Hence Y = 0','[{"s": "• For t ≤ t", "t": "text"}, {"s": "1", "t": "text"}, {"s": "; A = 0, B = 0; Hence Y = 0", "t": "text"}]',NULL,NULL,NULL),
(31037,74,415,'paragraph',NULL,'• For t 1 to t 2 ; A = 1, B = 0; Hence Y = 0','[{"s": "• For t", "t": "text"}, {"s": "1", "t": "text"}, {"s": "to t", "t": "text"}, {"s": "2", "t": "text"}, {"s": "; A = 1, B = 0; Hence Y = 0", "t": "text"}]',NULL,NULL,NULL),
(31038,74,416,'paragraph',NULL,'• For t 2 to t 3 ; A = 1, B = 1; Hence Y = 1','[{"s": "• For t", "t": "text"}, {"s": "2", "t": "text"}, {"s": "to t", "t": "text"}, {"s": "3", "t": "text"}, {"s": "; A = 1, B = 1; Hence Y = 1", "t": "text"}]',NULL,NULL,NULL),
(31039,74,417,'paragraph',NULL,'• For t 3 to t 4 ; A = 0, B = 1; Hence Y = 0','[{"s": "• For t", "t": "text"}, {"s": "3", "t": "text"}, {"s": "to t", "t": "text"}, {"s": "4", "t": "text"}, {"s": "; A = 0, B = 1; Hence Y = 0", "t": "text"}]',NULL,NULL,NULL),
(31040,74,418,'paragraph',NULL,'• For t 4 to t 5 ; A = 0, B = 0; Hence Y = 0','[{"s": "• For t", "t": "text"}, {"s": "4", "t": "text"}, {"s": "to t", "t": "text"}, {"s": "5", "t": "text"}, {"s": "; A = 0, B = 0; Hence Y = 0", "t": "text"}]',NULL,NULL,NULL),
(31041,74,419,'paragraph',NULL,'• For t 5 to t 6 ; A = 1, B = 0; Hence Y = 0','[{"s": "• For t", "t": "text"}, {"s": "5", "t": "text"}, {"s": "to t", "t": "text"}, {"s": "6", "t": "text"}, {"s": "; A = 1, B = 0; Hence Y = 0", "t": "text"}]',NULL,NULL,NULL),
(31042,74,420,'paragraph',NULL,'• For t > t 6 ; A = 0, B = 1; Hence Y = 0','[{"s": "• For t > t", "t": "text"}, {"s": "6", "t": "text"}, {"s": "; A = 0, B = 1; Hence Y = 0", "t": "text"}]',NULL,NULL,NULL),
