(31154,74,532,'paragraph',NULL,'1. The conductivity of a semiconductor increases with increase in temperature, because','[{"s": "1. The conductivity of a semiconductor increases with increase in temperature, because", "t": "text"}]',NULL,NULL,NULL),
(31155,74,533,'paragraph',NULL,'(1) number density of free current carries increases','[{"s": "(1) number density of free current carries increases", "t": "text"}]',NULL,NULL,NULL),
(31156,74,534,'paragraph',NULL,'(2) relaxation time increases','[{"s": "(2) relaxation time increases", "t": "text"}]',NULL,NULL,NULL),
(31157,74,535,'paragraph',NULL,'(3) both number density of carries and relaxation time increase','[{"s": "(3) both number density of carries and relaxation time increase", "t": "text"}]',NULL,NULL,NULL),
(31158,74,536,'paragraph',NULL,'(4) number density of carries increases, relaxation time decreases but effect of decrease in relaxation time is much less than increase in number density','[{"s": "(4) number density of carries increases, relaxation time decreases but effect of decrease in relaxation time is much less than increase in number density", "t": "text"}]',NULL,NULL,NULL),
(31159,74,537,'paragraph',NULL,'2. In figure given below V 0 is the potential barrier across a p-n junction, when no battery is connected across the junction','[{"s": "2. In figure given below V", "t": "text"}, {"s": "0", "t": "text"}, {"s": "is the potential barrier across a p-n junction, when no battery is connected across the junction", "t": "text"}]',NULL,NULL,NULL),
