(31215,74,593,'paragraph',NULL,'9. When an electric field is applied across a semiconductor','[{"s": "9. When an electric field is applied across a semiconductor", "t": "text"}]',NULL,NULL,NULL),
(31216,74,594,'paragraph',NULL,'(a) electrons move from lower energy level to higher energy level in the conduction band','[{"s": "(a) electrons move from lower energy level to higher energy level in the conduction band", "t": "text"}]',NULL,NULL,NULL),
(31217,74,595,'paragraph',NULL,'(b) electrons move from higher energy level to lower energy level in the conduction band','[{"s": "(b) electrons move from higher energy level to lower energy level in the conduction band", "t": "text"}]',NULL,NULL,NULL),
(31218,74,596,'paragraph',NULL,'(c) holes in the valence band move from higher energy level to lower energy level','[{"s": "(c) holes in the valence band move from higher energy level to lower energy level", "t": "text"}]',NULL,NULL,NULL),
(31219,74,597,'paragraph',NULL,'(d) holes in the valence band move from lower energy level to higher energy level','[{"s": "(d) holes in the valence band move from lower energy level to higher energy level", "t": "text"}]',NULL,NULL,NULL),
(31220,74,598,'paragraph',NULL,'10. Consider an n-p-n transitor with its base-emitter junction forward biased and collector base junction reverse biased. Which of the following statements are true?','[{"s": "10. Consider an n-p-n transitor with its base-emitter junction forward biased and collector base junction reverse biased. Which of the following statements are true?", "t": "text"}]',NULL,NULL,NULL),
(31221,74,599,'paragraph',NULL,'(a) Electrons crossover from emitter to collector','[{"s": "(a) Electrons crossover from emitter to collector", "t": "text"}]',NULL,NULL,NULL),
(31222,74,600,'paragraph',NULL,'(b) Holes move from base to collector','[{"s": "(b) Holes move from base to collector", "t": "text"}]',NULL,NULL,NULL),
(31223,74,601,'paragraph',NULL,'(c) Electrons move from emitter to base','[{"s": "(c) Electrons move from emitter to base", "t": "text"}]',NULL,NULL,NULL),
(31224,74,602,'paragraph',NULL,'(d) Electrons from emitter move out of base without going to the collector.','[{"s": "(d) Electrons from emitter move out of base without going to the collector.", "t": "text"}]',NULL,NULL,NULL),
