(31685,75,351,'paragraph',NULL,'Now, the velocity of the particle is v = d r /dt and p = m v','[{"s": "Now, the velocity of the particle is", "t": "text"}, {"s": "v", "t": "text"}, {"s": "= d", "t": "text"}, {"s": "r", "t": "text"}, {"s": "/dt and", "t": "text"}, {"s": "p", "t": "text"}, {"s": "= m", "t": "text"}, {"s": "v", "t": "text"}]',NULL,NULL,NULL),
(31686,75,352,'paragraph',NULL,'Because of this Systems_Of_Particles-image272.png','[{"s": "Because of this", "t": "text"}, {"s": "Systems_Of_Particles-image272.png", "t": "img", "alt": ""}]',NULL,NULL,NULL),
(31687,75,353,'paragraph',NULL,'as the vector product of two parallel vectors vanishes. Further, since d p / dt = F ,','[{"s": "as the vector product of two parallel vectors vanishes. Further, since d", "t": "text"}, {"s": "p", "t": "text"}, {"s": "/ dt =", "t": "text"}, {"s": "F", "t": "text"}, {"s": ",", "t": "text"}]',NULL,NULL,NULL),
