(31845,75,511,'paragraph',NULL,'or R 1 – R 2 = 1.2g N = 11.76 N (iv)','[{"s": "or R", "t": "text"}, {"s": "1", "t": "text"}, {"s": "– R", "t": "text"}, {"s": "2", "t": "text"}, {"s": "= 1.2g N = 11.76 N (iv)", "t": "text"}]',NULL,NULL,NULL),
(31846,75,512,'paragraph',NULL,'From (iii) and (iv), R 1 = 54.88 N,','[{"s": "From (iii) and (iv), R", "t": "text"}, {"s": "1", "t": "text"}, {"s": "= 54.88 N,", "t": "text"}]',NULL,NULL,NULL),
