(32553,76,71,'paragraph',NULL,'At constant pressure','[{"s": "At constant pressure", "t": "text"}]',NULL,NULL,NULL),
(32554,76,72,'paragraph',NULL,'P∆V = µR ∆T','[{"s": "P∆V = µR ∆T", "t": "text"}]',NULL,NULL,NULL),
(32555,76,73,'image',NULL,NULL,NULL,NULL,NULL,'/ncert/physics/images/Thermal_Properties_Of_Matter-image80.png'),
(32556,76,74,'paragraph',NULL,'i.e., Thermal_Properties_Of_Matter-image81.png for ideal gas (11.6)','[{"s": "i.e.,", "t": "text"}, {"s": "Thermal_Properties_Of_Matter-image81.png", "t": "img", "alt": ""}, {"s": "for ideal gas (11.6)", "t": "text"}]',NULL,NULL,NULL),
(32558,76,76,'paragraph',NULL,'∆l = αl l ∆T','[{"s": "∆l = αl l ∆T", "t": "text"}]',NULL,NULL,NULL),
