(33998,78,559,'paragraph',NULL,'2.1 Fill in the blanks.','[{"s": "2.1", "t": "text"}, {"s": "Fill in the blanks.", "t": "text"}]',NULL,NULL,NULL),
(33999,78,560,'paragraph',NULL,'(a) The volume of a cube of side 1 cm is equal to .....m 3','[{"s": "(a) The volume of a cube of side 1 cm is equal to .....m", "t": "text"}, {"s": "3", "t": "text"}]',NULL,NULL,NULL),
(34000,78,561,'paragraph',NULL,'(b) The surface area of a solid cylinder of radius 2.0 cm and height 10.0 cm is equal to .....(mm) 2','[{"s": "(b) The surface area of a solid cylinder of radius 2.0 cm and height 10.0 cm is equal to .....(mm)", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(34001,78,562,'paragraph',NULL,'(c) A vehicle moving with a speed of 18 km h –1 covers ......m in 1 s','[{"s": "(c) A vehicle moving with a speed of 18 km h", "t": "text"}, {"s": "–1", "t": "text"}, {"s": "covers ......m in 1 s", "t": "text"}]',NULL,NULL,NULL),
(34002,78,563,'paragraph',NULL,'(d) The relative density of lead is 11.3. Its density is ....g cm –3 or ....kg m –3 .','[{"s": "(d) The relative density of lead is 11.3. Its density is ....g cm", "t": "text"}, {"s": "–3", "t": "text"}, {"s": "or ....kg m", "t": "text"}, {"s": "–3", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(34003,78,564,'paragraph',NULL,'2.2 Fill in the blanks by suitable conversion of units.','[{"s": "2.2", "t": "text"}, {"s": "Fill in the blanks by suitable conversion of units.", "t": "text"}]',NULL,NULL,NULL),
(34004,78,565,'paragraph',NULL,'(a) 1 kg m 2 s –2 = ....g cm 2 s –2','[{"s": "(a) 1 kg m", "t": "text"}, {"s": "2", "t": "text"}, {"s": "s", "t": "text"}, {"s": "–2", "t": "text"}, {"s": "= ....g cm", "t": "text"}, {"s": "2", "t": "text"}, {"s": "s", "t": "text"}, {"s": "–2", "t": "text"}]',NULL,NULL,NULL),
