(34506,79,426,'paragraph',NULL,'Q. 4 Ina Young\'s double-slit experiment, the source is white light. One of the holes is covered by a red filter and another by a blue filter. In this case,','[{"s": "Q. 4 Ina Young\'s double-slit experiment, the source is white light. One of the holes is covered by a red filter and another by a blue filter. In this case,", "t": "text"}]',NULL,NULL,NULL),
(34507,79,427,'paragraph',NULL,'(1) there shall be alternate interference patterns of red and blue','[{"s": "(1) there shall be alternate interference patterns of red and blue", "t": "text"}]',NULL,NULL,NULL),
(34508,79,428,'paragraph',NULL,'(2) there shall be an interference pattern for red distinct from that for blue','[{"s": "(2) there shall be an interference pattern for red distinct from that for blue", "t": "text"}]',NULL,NULL,NULL),
