(34526,79,446,'paragraph',NULL,'Q. 7 Consider sunlight incident on a pinhole of width 10 3 ∘ A. The image of the pinhole seen on a screen shall be','[{"s": "Q. 7 Consider sunlight incident on a pinhole of width 10", "t": "text"}, {"s": "3", "t": "text"}, {"s": "∘", "t": "text"}, {"s": "A. The image of the pinhole seen on a screen shall be", "t": "text"}]',NULL,NULL,NULL),
(34527,79,447,'paragraph',NULL,'(1) a sharp white ring','[{"s": "(1) a sharp white ring", "t": "text"}]',NULL,NULL,NULL),
(34528,79,448,'paragraph',NULL,'(2) different from a geometrical image','[{"s": "(2) different from a geometrical image", "t": "text"}]',NULL,NULL,NULL),
(34529,79,449,'paragraph',NULL,'(3) a diffused central spot, white in colour','[{"s": "(3) a diffused central spot, white in colour", "t": "text"}]',NULL,NULL,NULL),
(34530,79,450,'paragraph',NULL,'(4) diffused coloured region around a sharp central white spot','[{"s": "(4) diffused coloured region around a sharp central white spot", "t": "text"}]',NULL,NULL,NULL),
(34531,79,451,'paragraph',NULL,'Q. 8 Consider the diffraction pattern for a small pinhole. As the size of the hole is increased','[{"s": "Q. 8 Consider the diffraction pattern for a small pinhole. As the size of the hole is increased", "t": "text"}]',NULL,NULL,NULL),
(34532,79,452,'paragraph',NULL,'(1) the size decreases','[{"s": "(1) the size decreases", "t": "text"}]',NULL,NULL,NULL),
