(34536,79,456,'paragraph',NULL,'Q. 9 for light diverging from a point source,','[{"s": "Q. 9 for light diverging from a point source,", "t": "text"}]',NULL,NULL,NULL),
(34537,79,457,'paragraph',NULL,'(a) the wavefront is spherical','[{"s": "(a) the wavefront is spherical", "t": "text"}]',NULL,NULL,NULL),
(34538,79,458,'paragraph',NULL,'(b) the intensity decreases in proportion to the distance squared','[{"s": "(b) the intensity decreases in proportion to the distance squared", "t": "text"}]',NULL,NULL,NULL),
(34539,79,459,'paragraph',NULL,'(c) the wavefront is parabolic','[{"s": "(c) the wavefront is parabolic", "t": "text"}]',NULL,NULL,NULL),
(34540,79,460,'paragraph',NULL,'(d) the intensity at the wavefront does not depend on the distance','[{"s": "(d) the intensity at the wavefront does not depend on the distance", "t": "text"}]',NULL,NULL,NULL),
(34541,79,461,'paragraph',NULL,'Q.18 Consider a two-slit interference arrangement (figure) such that the distance of the screen from the slits is half the distance between the slits. Obtanin the value of D in terms of λ such that the first minima on the screen falls at a distance D from the centre.','[{"s": "Q.18 Consider a two-slit interference arrangement (figure) such that the distance of the screen from the slits is half the distance between the slits. Obtanin the value of D in terms of", "t": "text"}, {"s": "λ", "t": "text"}, {"s": "such that the first minima on the screen falls at a distance D from the centre.", "t": "text"}]',NULL,NULL,NULL),
