(35554,81,317,'paragraph',NULL,'The change in kinetic energy is','[{"s": "The change in kinetic energy is", "t": "text"}]',NULL,NULL,NULL),
(35555,81,318,'paragraph',NULL,'∆K = K f − K i Work_Energy_and_Power-image67.png','[{"s": "∆K = K", "t": "text"}, {"s": "f", "t": "text"}, {"s": "− K", "t": "text"}, {"s": "i", "t": "text"}, {"s": "Work_Energy_and_Power-image67.png", "t": "img", "alt": ""}]',NULL,NULL,NULL),
